// lib/env-secrets.js —— .env 私密配置：dotenv 解析 → ToolHive 加密凭据库 → 部署时 --secret 注入。
// 值全程不进 DB/命令行/日志/审计（2026-09-05 设计定稿）。从 server.js 拆出（2026-09-07）。
"use strict";

module.exports = function makeEnvSecrets(ctx) {
  const { THV_BIN, db, parseMeta, patchMeta, actorFromReq, workloadNameFor, audit } = ctx;

// ---- 源码包 MCP：.env secrets 注入 + 自动构建（docker build）----
// 设计（2026-09-05 定稿）：
//   · .env 单独上传，值经 `thv secret set`（stdin 管道，不进命令行）入 ToolHive
//     加密凭据库（AES-256-GCM + OS keyring）；平台 DB 只存键名与 secret 引用名。
//   · 部署时注入 `-e KEY=${secret:<name>}`——明文值全程只在凭据库与容器启动瞬间出现。
//   · 源码 zip（package.json / requirements.txt 识别）构建本地镜像后走既有部署链。
//   · 审计只记键数；值不入 DB/日志/审计。

// dotenv 标准解析：忽略空行与 # 注释；支持 export 前缀；值剥离成对引号；
// 未加引号时行内 # 起注释（前值保留 trim）。返回 { KEY: value }。
function parseDotenv(text) {
  const out = {};
  for (const rawLine of String(text || "").split(/\r?\n/)) {
    let line = rawLine.trim();
    if (!line || line.startsWith("#")) continue;
    if (line.startsWith("export ")) line = line.slice(7).trim();
    const eq = line.indexOf("=");
    if (eq <= 0) continue;
    const key = line.slice(0, eq).trim();
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) continue;
    let val = line.slice(eq + 1).trim();
    const q = val[0];
    if ((q === '"' || q === "'") && val.endsWith(q) && val.length >= 2) {
      val = val.slice(1, -1);
    } else {
      const hash = val.indexOf(" #");
      if (hash !== -1) val = val.slice(0, hash).trim();
    }
    out[key] = val;
  }
  return out;
}

// 静态扫描源码文本，提取代码声明的环境变量需求键（用于 .env 缺键告警）。
function scanSourceEnvKeys(text) {
  const keys = new Set();
  const patterns = [
    /process\.env\.([A-Za-z_][A-Za-z0-9_]*)/g,
    /process\.env\[[\s]*["']([A-Za-z_][A-Za-z0-9_]*)["']/g,
    /os\.environ(?:\.get)?\(\s*["']([A-Za-z_][A-Za-z0-9_]*)["']/g,
    /os\.getenv\(\s*["']([A-Za-z_][A-Za-z0-9_]*)["']/g,
    /os\.environ\[["']([A-Za-z_][A-Za-z0-9_]*)["']\]/g,
  ];
  for (const re of patterns) {
    let m;
    while ((m = re.exec(text)) !== null) keys.add(m[1]);
  }
  return [...keys];
}

// 用 spawnSync 的 stdin 传值写入 ToolHive 加密凭据库（值不进命令行/进程列表）。
function thvSecretSet(name, value) {
  const r = require("child_process").spawnSync(
    THV_BIN, ["secret", "set", name],
    { input: value, encoding: "utf8", windowsHide: true, timeout: 30000 },
  );
  if (r.status !== 0) throw new Error(`secret set ${name} 失败: ${(r.stderr || r.stdout || "").slice(0, 200)}`);
}
function thvSecretDelete(name) {
  const r = require("child_process").spawnSync(
    THV_BIN, ["secret", "delete", name],
    { encoding: "utf8", windowsHide: true, timeout: 30000 },
  );
  return r.status === 0;
}

// 上传 .env：解析 → 逐键写入凭据库 → meta.env_refs（KEY→secret名）与 env_keys。
// secret 命名：mcp-<submission_id>-<key 小写>，与条目一一绑定，杜绝跨条目错配。
function secretNameFor(sid, key) {
  return `mcp-${String(sid).toLowerCase()}-${key.toLowerCase()}`;
}
async function storeSubmissionEnv(req, res, sub) {
  const actor = actorFromReq(req);
  const isOwner = actor.email && String(sub.user_id || "").toLowerCase() === actor.email.toLowerCase();
  if (!actor.admin && !isOwner) return res.status(403).json({ error: "仅提交者本人或管理员可配置环境变量" });
  if (sub.type !== "mcp") return res.status(400).json({ error: "仅 MCP 条目支持环境变量" });

  const raw = Buffer.isBuffer(req.body) ? req.body.toString("utf8") : "";
  if (!raw.trim()) return res.status(400).json({ error: "缺少 .env 内容" });
  const parsed = parseDotenv(raw);
  const keys = Object.keys(parsed);
  if (keys.length === 0) return res.status(400).json({ error: "未解析出任何 KEY=VALUE 条目" });

  const meta = parseMeta(sub);
  const workload = meta.workload_name || workloadNameFor(sub.id);
  const refs = {};
  try {
    for (const key of keys) {
      const name = secretNameFor(sub.id, key);
      thvSecretSet(name, parsed[key]);
      refs[key] = name;
    }
  } catch (e) {
    // 失败即回滚已写入的键，避免半套配置
    for (const name of Object.values(refs)) thvSecretDelete(name);
    return res.status(500).json({ error: "凭据库写入失败: " + e.message });
  }
  patchMeta(sub.id, {
    env_refs: refs,
    env_keys: keys,
    env_updated_at: new Date().toISOString(),
  });
  // 审计只记键名清单与数量，绝不记值
  audit(req, "env_configured", sub.type, sub.id, { keys, count: keys.length });
  res.json({ id: sub.id, keys, count: keys.length });
}

// 删除条目的全部 secrets（removed/rejected 清理时调用；值不回传）
function deleteSubmissionSecrets(id) {
  const sub = db.prepare("SELECT meta FROM submissions WHERE id=?").get(id);
  if (!sub) return;
  const meta = parseMeta(sub);
  const refs = meta.env_refs || {};
  for (const name of Object.values(refs)) {
    try { thvSecretDelete(name); } catch (_) { /* 幂等清理，单个失败不阻断 */ }
  }
}

// 部署时把 secrets 引用转成 thv run 的 --secret 参数：
// --secret <secret 名>,target=<KEY> —— ToolHive 启动容器时向凭据库请求解密并注入目标环境变量。
// 官方语法（勿用 -e ${secret:}，那会被原样传入不解析）。
function envInjectArgs(meta) {
  const refs = meta.env_refs || {};
  const args = [];
  for (const [key, secretName] of Object.entries(refs)) {
    args.push("--secret", `${secretName},target=${key}`);
  }
  return args;
}

// ---- 应用自带鉴权（API Key）时，平台代为携带 ----
// 场景：源码 MCP 应用从注入的 env 里读 API Key 做请求鉴权（如 RETAIL_MCP_API_KEY）。
// 平台探测（/mcp/:id/tools）、代调（/mcp/call）、反向代理（/mcp-proxy）都需要携带，
// 否则 initialize/tools/list 全被 401 挡住，详情页工具显示为空、用户也无法调用。
// 值仍从凭据库读回（thv secret get），只在服务端内存短暂缓存，不落盘不进日志。

const secretValueCache = new Map(); // secret 名 -> { v, at }，5 分钟 TTL
function thvSecretGetValue(name) {
  const c = secretValueCache.get(name);
  if (c && Date.now() - c.at < 5 * 60 * 1000) return c.v;
  let r;
  try {
    r = require("child_process").spawnSync(
      THV_BIN, ["secret", "get", String(name)],
      { encoding: "utf8", windowsHide: true, timeout: 15000 },
    );
  } catch (_) {
    return null;
  }
  if (r.status !== 0) return null;
  const v = String(r.stdout || "").trim();
  if (!v) return null;
  secretValueCache.set(name, { v, at: Date.now() });
  return v;
}

// 疑似鉴权凭证的 env 键名匹配与优先级（API Key > Token > Auth > Secret）。
const AUTH_KEY_RE = /API_?KEY|API_?TOKEN|ACCESS_?TOKEN|AUTH_?TOKEN|_TOKEN$|^TOKEN$|API_?SECRET|_SECRET$|AUTHORIZATION|^AUTH$|BEARER/i;
function authKeyPriority(key) {
  if (/API_?KEY|API_?TOKEN/i.test(key)) return 0;
  if (/TOKEN/i.test(key)) return 1;
  if (/AUTH|BEARER/i.test(key)) return 2;
  return 3;
}

// 返回该条目可用的鉴权头候选列表（按优先级降序）。每个候选同时带
// Authorization: Bearer 与 X-Api-Key 两种形态，兼容两类常见校验方式。
function authHeaderCandidates(meta) {
  const keys = (meta && meta.env_keys) || [];
  const refs = (meta && meta.env_refs) || {};
  return keys
    .filter((k) => AUTH_KEY_RE.test(k) && refs[k])
    .sort((a, b) => authKeyPriority(a) - authKeyPriority(b))
    .map((k) => {
      const v = thvSecretGetValue(refs[k]);
      return v ? { Authorization: `Bearer ${v}`, "X-Api-Key": v } : null;
    })
    .filter(Boolean);
}

  return {
    parseDotenv, scanSourceEnvKeys, thvSecretSet, thvSecretDelete, secretNameFor,
    storeSubmissionEnv, deleteSubmissionSecrets, envInjectArgs,
    authHeaderCandidates,
  };
};

// lib/ingress.js —— ToolHive ingress 端口发现与端点解析（2026-09-18 自 server.js 拆出，渐进式拆分第五步）
// 覆盖：WSL2 端口改写（rewriteForWsl2）/ 平台固定端口优先的端点发现
//   （discoverIngressForSubmission）/ thv 镜像别名发现（discoverThvEndpoint）/ 统一入口
//   （resolveEndpoint）。
// 注意：getIngressPort / ensureStableIngress / rebuildIngress / healMcpIngress 在
//   lib/ingress-heal.js（健康探测自愈层，耦合 db/patchMeta 与自愈任务表）——本模块经 ctx
//   注入使用，依赖方向单向：ingress → ingress-heal，无装配循环。
const fs = require("node:fs");

module.exports = function createIngress(ctx) {
  const {
    execFileHidden, MAX_BUFFER, parseMeta, workloadNameFor,
    getIngressPort, ensureStableIngress, thvListJson, MCP_IMAGE_ALIASES, LIVE_ENDPOINTS,
  } = ctx;

  // 默认【不改写】：当前后端与 ToolHive MCP server 同处 WSL2，Docker 已把容器
  // 端口转发到 WSL2 的 127.0.0.1，直接用即可。若 server 真在 Windows 主机、需跨
  // 网络访问，再设 WSL2_REWRITE=1 启用改写（把 127.0.0.1 换成 Windows 主机 IP）。
  function rewriteForWsl2(url) {
    if (process.env.WSL2_REWRITE !== "1" || process.platform !== "linux") return url;
    try {
      const osrelease = fs.readFileSync("/proc/sys/kernel/osrelease", "utf8");
      if (!/microsoft|wsl/i.test(osrelease)) return url;
      const resolv = fs.readFileSync("/etc/resolv.conf", "utf8");
      const m = resolv.match(/nameserver\s+(\d+\.\d+\.\d+\.\d+)/);
      const winIp = m && m[1];
      if (!winIp || winIp.startsWith("127.")) return url;
      return url.replace(/^(https?:\/\/)(127\.0\.0\.1|localhost)(:|\/)/, `$1${winIp}$3`);
    } catch (_) {
      return url;
    }
  }

  // 对平台已提交的 MCP，动态发现当前可达的 ingress 端口（优先平台固定端口）。
  // 背景：ToolHive 部署时 thv list 先报告内部端口（如 127.0.0.1:21784），此时 ingress
  // 容器尚未创建，导致写入 meta.endpoint 的端口浏览器无法访问。详情/调用时重新查一次。
  // ensureStableIngress 幂等：固定端口可用时秒回；坏/缺 ingress 时重建（端口不变）。
  async function discoverIngressForSubmission(sub, opts = {}) {
    if (!sub || sub.type !== "mcp") return null;
    const meta = parseMeta(sub);
    const workload = meta.workload_name || workloadNameFor(sub.id);
    const p = await ensureStableIngress(workload, meta, opts);
    if (p) return `http://127.0.0.1:${p}/mcp`;
    return meta.endpoint || null;
  }

  async function discoverThvEndpoint(ref) {
    if (!ref) return null;
    const alias = MCP_IMAGE_ALIASES[ref] || ref;
    const list = await thvListJson();
    const entry = list.find((x) =>
      x.status === "running" &&
      (x.name === ref || (x.package && x.package.includes(alias)))
    );
    if (!entry) return null;
    // thv list 报告的 url 可能不是实际可访问的 ingress 端口（如 14801 不可达，
    // 而 Docker 实际映射的是 13433），优先用 docker port 取 ingress 容器端口。
    const ingressPort = await getIngressPort(entry.name);
    if (ingressPort) return `http://127.0.0.1:${ingressPort}/mcp`;
    return entry.url || null;
  }

  async function resolveEndpoint(ref, explicit) {
    if (explicit) return explicit;
    if (ref && /^https?:\/\//.test(ref)) return ref;
    // 优先运行时动态发现 ToolHive 实际端口，避免硬编码端口失效
    const discovered = await discoverThvEndpoint(ref);
    if (discovered) return discovered;
    if (ref && LIVE_ENDPOINTS[ref]) return LIVE_ENDPOINTS[ref];
    return null;
  }

  return { rewriteForWsl2, discoverIngressForSubmission, discoverThvEndpoint, resolveEndpoint };
};

// lib/visibility.js —— 可见性判定纯函数集（2026-10-08 自 server.js 抽出，逻辑零改动）。
// 抽出目的：可被 node:test 直接单测（无 IO、无状态）；server.js require 后行为不变。
"use strict";

/** visibility 缺省视为全员可见（兼容历史数据与未配置条目）。 @param {Object} meta @returns {Visibility} */
function parseVisibility(meta) {
  const v = meta && meta.visibility;
  if (!v || v.mode !== "restricted")
    return { mode: "all", users: [], groups: [] };
  // 归一化：丢弃 null/undefined（原实现 String(null)="null" 会混进白名单，抽库时顺手加固）
  const norm = (arr) =>
    (Array.isArray(arr) ? arr : [])
      .filter((s) => s != null)
      .map((s) => String(s).toLowerCase().trim())
      .filter(Boolean);
  return {
    mode: "restricted",
    users: norm(v.users),
    groups: norm(v.groups),
  };
}

/** 条目是否已「上线」：仅当管理员显式配置过可见范围后，才对非管理员开放可见/下载/调用。
 *  存量条目无 visibility_configured 字段 → 视为已上线（向后兼容，不强制重配）；
 *  新提交默认 visibility_configured=false → 未上线，仅管理员在「已发布管理」可见，待配可见范围。
 *  @param {Object} meta @returns {boolean} */
function isOnShelf(meta) {
  return !(meta && meta.visibility_configured === false);
}

/** 可见性判定单一入口：admin 恒通过 → 未上架拒绝 → mode=all 通过 → restricted 按 users/groups 命中。
 *  列表过滤、详情、下载、代理调用必须全部走这里，禁止各自内联判定。
 *  @param {Object} meta @param {Actor|null} actor @returns {boolean} */
function canAccessSubmission(meta, actor) {
  if (!actor || actor.admin) return true;
  // 未上线的条目只对管理员可见（普通用户/匿名一律不可见不可调用）
  if (!isOnShelf(meta)) return false;
  const v = parseVisibility(meta);
  if (v.mode !== "restricted") return true;
  if (actor.email && v.users.includes(actor.email)) return true;
  if (Array.isArray(actor.groups) && actor.groups.some((g) => v.groups.includes(g)))
    return true;
  return false;
}

/** 成员级代理 Token 是否可用（2026-10-14 修订：任何可见性模式下均可用，凭证与模式彻底解耦）。
 *  旧规则（mode!=="restricted" 一律 false）已废除——mode=all 下名单 = 已自助签发/管理员
 *  添加的成员，其个人 token 用于调用归因；restricted 下名单即准入名单（不变）。
 *  注意必须读原始 meta.visibility.users——parseVisibility() 在 mode=all 时丢弃名单。
 *  proxy 每次请求实时调用本函数：移出名单即刻失效。
 *  @param {Object} meta @param {string} member @returns {boolean} */
function memberTokenAllowed(meta, member) {
  const m = String(member || "").toLowerCase().trim();
  if (!m) return false;
  const v = meta && meta.visibility;
  const users = Array.isArray(v && v.users) ? v.users : [];
  return users.some((u) => String(u).toLowerCase().trim() === m);
}

/** 可见范围保存解析（2026-10-14）：名单与模式解耦，防止 UI 保存覆盖掉已收编名单。
 *  背景：收编脚本 merge-users 写入的名单，曾被 UI「可见范围」弹窗保存时整体覆盖为
 *  mode=all + 空名单（旧路由对缺省 users 写 []），导致成员 token 被遮蔽、需要人工恢复。
 *  规则：
 *   - mode=all：users/groups 一律保留现值，payload 里的名单字段忽略——全员可见下名单
 *     不参与判定，但保留后切回 restricted 不丢名单；
 *   - mode=restricted：显式提供（Array.isArray）才覆盖，缺省保留现值；
 *   - mode=restricted 且解析结果 users 为空、但库里有成员 token 时：自动并入成员邮箱
 *     （adoptMembers=true，由路由写 audit），避免管理员误保存空名单后全部成员 token 失联。
 *  @param {Object|null} prev 现存 visibility（meta.visibility，可为 null）
 *  @param {Object} body 请求体 { mode, users?, groups? }
 *  @param {string[]} memberEmails 该条目已签发成员 token 的邮箱（归一化前即可）
 *  @returns {{visibility: {mode:string,users:string[],groups:string[]}, adoptMembers: boolean}} */
function resolveVisibilitySave(prev, body, memberEmails) {
  const norm = (arr) =>
    (Array.isArray(arr) ? arr : [])
      .filter((s) => s != null)
      .map((s) => String(s).toLowerCase().trim())
      .filter(Boolean);
  const prevMode = prev && prev.mode === "restricted" ? "restricted" : "all";
  const prevUsers = norm(prev && prev.users);
  const prevGroups = norm(prev && prev.groups);
  const b = body || {};
  const mode = b.mode === "restricted" ? "restricted" : "all";
  if (mode === "all") {
    // 全员可见：名单无判定意义，保留现值（payload 中的名单字段忽略）
    return { visibility: { mode, users: prevUsers, groups: prevGroups }, adoptMembers: false };
  }
  const hasUsers = Array.isArray(b.users);
  const hasGroups = Array.isArray(b.groups);
  let users = hasUsers ? norm(b.users) : prevUsers;
  const groups = hasGroups ? norm(b.groups) : prevGroups;
  let adoptMembers = false;
  if (users.length === 0 && norm(memberEmails).length > 0) {
    users = norm(memberEmails);
    adoptMembers = true;
  }
  return { visibility: { mode, users, groups }, adoptMembers };
}

module.exports = { parseVisibility, isOnShelf, canAccessSubmission, memberTokenAllowed, resolveVisibilitySave };

// routes/mcp.js —— MCP 路由域（2026-09-11 渐进式拆分第三步，自 server.js 原样迁出）
// 覆盖：列表 / 单条 / 文件预览 / tools(SWR) / call / rotate-token，
//   以及 rtCache（实例运行时缓存）与 toolsCache（tools 清单缓存）两层 SWR。
// 注意：/mcp-proxy 的回环注册（4000，express.json 之前）与对外监听（4100）仍留在 server.js——
//   前者对中间件链顺序敏感（必须在 express.json 之前），后者是安全边界，二者不宜随本模块迁移。
// 依赖经 ctx 注入（全部为 server.js 中的声明式函数或先于此装配的常量）：
const crypto = require("node:crypto");
const http = require("node:http");
const express = require("express");
const { parseVisibility, memberTokenAllowed } = require("../lib/visibility");
const { normalizeEmail, normalizeEmails, readUsers, readRawVisibility, visibilityWithMember, issueOrRotateToken } = require("../lib/member-tokens");

module.exports = function registerMcpRoutes(app, ctx) {
  const {
    db, parseMeta, patchMeta, actorFromReq, audit, deniedThrottled,
    canAccessSubmission, pickDisplayVersions, isOnShelf, LIVE_MCPS,
    discoverIngressForSubmission, probeMcpEndpoint, discoverThvEndpoint,
    resolveMcpProxyTarget, subIdByWorkload, healMcpIngress,
    mapMcpRow, publicEndpointFor, mcpAuthHeadersFor, getOrCreateMcpToken,
    authHeaderCandidates, mcpCallAuthed, rewriteForWsl2, resolveEndpoint,
    workloadNameFor, servePackageFile, execFileHidden, MAX_BUFFER,
    inspectSkillPackage, MCP_TREE_MAX,
  } = ctx;

  // ---- 成员级代理 Token（双轨制 2026-10-13；D1 修订 2026-10-14：凭证与可见性模式解耦）----
  // 按调用者身份出代理凭证（D1 修订后语义）：
  //  - admin → 包级 token（应急/管理员专用，不再作为普通成员凭证下发）；
  //  - 普通成员 → 一律个人成员 token（任何可见性模式，含 mode=all / groups），
  //    未签发则不出 headers、置 mcp_token_required=true，前端引导走自助签发
  //    （POST /submissions/:id/my-member-token，资格在签发时按 actor 身份+groups 判定）。
  //  修订理由：包级共享凭证无法按人轮换/审计（caller=package），是 agent 管控的盲区。
  // 返回 { headers, tokenRequired }：headers 供 mcp_headers 字段，tokenRequired 供前端区分「无凭证」与「未签发」。
  function mcpHeadersForActor(s, actor) {
    const meta = parseMeta(s);
    const workload = meta.workload_name || workloadNameFor(s.id);
    if (actor.admin) {
      const headers = mcpAuthHeadersFor(workload); // 副作用：确保包级 token 存在（管理员/应急路径依赖）
      return { headers, tokenRequired: false };
    }
    const member = String(actor.email || "").toLowerCase().trim();
    const mt = member
      ? db.prepare("SELECT token FROM mcp_member_tokens WHERE submission_id=? AND member=?").get(s.id, member)
      : null;
    if (mt) return { headers: { Authorization: `Bearer ${mt.token}` }, tokenRequired: false };
    return { headers: undefined, tokenRequired: true };
  }

  // ---- 实例运行时缓存（SWR）：ingress 端点发现（docker 查询）+ 真实探活 ----
  // /mcp 列表与 /mcp/:id 每次都对每个实例做 docker 查询 + HTTP 探活（各 ~450ms），
  // 目录页 N 轮版本聚合叠加后严重拖慢导航。策略与 toolsCache 一致：
  //   fresh 60s 直接回缓存；stale 回旧值 + 后台单飞刷新；失败负缓存 30s；
  //   deploy/undeploy 主动失效（经本模块返回的 invalidate）。
  const RT_FRESH_MS = 60_000;
  const RT_FAIL_MS = 30_000;
  const rtCache = new Map(); // id -> { endpoint, healthy, ts, failed }
  const rtInflight = new Map(); // id -> Promise（单飞锁）

  // 单飞执行：同 id 并发共享同一次 docker 查询 + 探活，完成后写缓存
  function rtFetchSingleFlight(id, s, opts = {}) {
    let p = rtInflight.get(id);
    if (p) return p;
    p = (async () => {
      try {
        const ep = await discoverIngressForSubmission(s, opts);
        if (!ep) return { endpoint: null, healthy: false, failed: true };
        const healthy = await probeMcpEndpoint(ep);
        return { endpoint: ep, healthy, failed: !healthy };
      } catch (e) {
        return { endpoint: null, healthy: false, failed: true, error: String((e && e.message) || e) };
      }
    })()
      .then((r) => {
        rtCache.set(id, { ...r, ts: Date.now() });
        return r;
      })
      .finally(() => rtInflight.delete(id));
    rtInflight.set(id, p);
    return p;
  }

  // ---- tools 清单缓存（SWR）：详情页每点一次都实时握手太慢（秒级）----
  //   fresh（60s 内）→ 直接回缓存；stale（60s 后）→ 立即回旧值 + 后台单飞刷新；
  //   miss → 现场拉取（并发共享单飞）。失败结果做 30s 负缓存，防对挂掉实例的重试风暴。
  const TOOLS_FRESH_MS = 60_000;
  const TOOLS_FAIL_MS = 30_000;
  const toolsCache = new Map(); // id -> { result, ts, failed }
  const toolsInflight = new Map(); // id -> Promise（单飞锁：同 id 并发共享一次握手）

  // 现场拉取（原 handler 主体抽出）：无实例/失败均优雅降级，8s 超时防挂住
  async function fetchToolsLive(id) {
    let s = db.prepare("SELECT * FROM submissions WHERE id=?").get(id);
    let ep = null;
    if (s) {
      ep = await discoverIngressForSubmission(s);
    } else {
      for (const m of LIVE_MCPS) {
        const e = await discoverThvEndpoint(m.item_ref);
        if (e && m.id === id) { ep = e; break; }
      }
    }
    if (!ep) return { tools: [], live: false };
    const timeout = new Promise((_, rej) => setTimeout(() => rej(new Error("tools/list 超时")), 8000));
    try {
      const r = await Promise.race([mcpCallAuthed(ep, {}, s ? parseMeta(s) : {}), timeout]);
      const last = (r.events && r.events[r.events.length - 1]) || {};
      const tools = last.result && Array.isArray(last.result.tools) ? last.result.tools : [];
      return {
        live: true,
        tools: tools.map((t) => ({
          name: t.name,
          description: t.description || "",
          // 前端按 schema 生成参数模板（字段名/类型/必填），剥离后模板会退化成 {}
          ...(t.inputSchema ? { inputSchema: t.inputSchema } : {}),
        })),
      };
    } catch (e) {
      return { tools: [], live: false, failed: true, error: String((e && e.message) || e) };
    }
  }

  // 单飞执行：同 id 并发共享同一个进行中的刷新，完成后写缓存
  function toolsFetchSingleFlight(id) {
    let p = toolsInflight.get(id);
    if (p) return p;
    p = fetchToolsLive(id)
      .then((r) => {
        toolsCache.set(id, { result: r, ts: Date.now(), failed: !r.live });
        return r;
      })
      .catch((e) => {
        const r = { tools: [], live: false, failed: true, error: String((e && e.message) || e) };
        toolsCache.set(id, { result: r, ts: Date.now(), failed: true });
        return r;
      })
      .finally(() => toolsInflight.delete(id));
    toolsInflight.set(id, p);
    return p;
  }

  // 已审批 mcp 列表（供 /catalog 浏览页）。多版本场景下每 group 只展示最新已上架的版本。
  app.get("/mcp", async (req, res) => {
    const actor = actorFromReq(req);
    const rows = db.prepare(
      "SELECT * FROM submissions WHERE type='mcp' AND status='approved' ORDER BY created_at DESC"
    ).all();
    // 可见性过滤：restricted 条目仅对被授权的成员/组与管理员可见
    const displayRows = pickDisplayVersions(rows)
      .filter((s) => canAccessSubmission(parseMeta(s), actor));
    const calls = db.prepare(
      "SELECT item_ref, COUNT(*) c FROM metric_events WHERE item_type='mcp' AND event='call' GROUP BY item_ref"
    ).all();
    const callMap = {};
    calls.forEach((c) => { callMap[c.item_ref] = c.c; });
    const favs = db.prepare(
      "SELECT item_ref, COUNT(*) c FROM favorites WHERE item_type='mcp' GROUP BY item_ref"
    ).all();
    const favMap = {};
    favs.forEach((f) => { favMap[f.item_ref] = f.c; });
    for (const m of LIVE_MCPS) {
      const ep = await discoverThvEndpoint(m.item_ref);
      if (ep) m.endpoint = ep;
    }
    // 已部署的 MCP 重新发现一次真实 ingress 端口（meta 里存的是部署瞬间的内部端口，
    // 容器重建后会漂移）。每个项一次 docker port 调用，故并发执行并限制条数，
    // 避免条目多时把列表接口拖慢。
    const deployed = displayRows
      .filter((s) => parseMeta(s).deploy_status === "deployed")
      .slice(0, 30);
    // 实例运行时缓存（SWR）：docker 查询 + 探活不再每次全量重做（原先每项 ~450ms）
    const epMap = new Map();
    const rtMissing = [];
    for (const s of deployed) {
      const c = rtCache.get(s.id);
      if (!c) { rtMissing.push(s); continue; }
      const age = Date.now() - c.ts;
      const ttl = c.failed ? RT_FAIL_MS : RT_FRESH_MS;
      // 过期不阻塞：立即用旧值，后台单飞刷新（失败负缓存过期后暂不采用，等刷新结果）
      if (age > ttl && !rtInflight.has(s.id)) rtFetchSingleFlight(s.id, s, { rebuild: false });
      if (!(c.failed && age > RT_FAIL_MS) && c.endpoint) {
        epMap.set(s.id, { endpoint: c.endpoint, healthy: c.healthy });
      }
    }
    await Promise.all(
      rtMissing.map(async (s) => {
        const r = await rtFetchSingleFlight(s.id, s, { rebuild: false });
        if (!r.failed && r.endpoint) {
          epMap.set(s.id, { endpoint: r.endpoint, healthy: r.healthy });
        }
      }),
    );
    const mcpRows = displayRows.map((s) => {
      const row = mapMcpRow(s, callMap, favMap);
      const found = epMap.get(s.id);
      if (found) row.endpoint = found.endpoint;
      // 供列表卡片「复制配置」使用：走后端代理的固定地址（非 127.0.0.1 直连端口）
      if (row.endpoint) {
        row.healthy = found ? found.healthy : false;
        // 不可达就不给对外地址，否则用户复制过去是 502
        if (row.healthy) {
          row.public_endpoint = publicEndpointFor(
            parseMeta(s).workload_name || workloadNameFor(s.id),
            row.endpoint,
            req,
          );
          const { headers: actorTokenHeaders, tokenRequired } = mcpHeadersForActor(s, actor);
          row.mcp_headers = actorTokenHeaders;
          if (tokenRequired) row.mcp_token_required = true;
        }
      }
      return row;
    });

    const liveRows = await Promise.all(
      LIVE_MCPS.map(async (m) => {
        const healthy = m.endpoint ? await probeMcpEndpoint(m.endpoint) : undefined;
        return {
          ...m,
          healthy,
          public_endpoint: healthy
            ? publicEndpointFor(m.item_ref, m.endpoint, req)
            : undefined,
          mcp_headers: healthy ? mcpAuthHeadersFor(m.item_ref) : undefined,
          call_count: callMap[m.id] || 0,
          favorite_count: favMap[m.id] || 0,
          created_at: m.created_at || new Date().toISOString(),
        };
      }),
    );
    res.json([...mcpRows, ...liveRows]);
  });

  // ---- 镜像元数据提取（docker inspect，供详情页「代码」标签展示）----
  // 安全红线：Env 一律不提取不展示（镜像常在 ENV 里内置密钥）；entrypoint/cmd 参数与
  // labels 按敏感模式（password/secret/token/api key/credential/auth 等）脱敏后才返回。
  const INSPECT_SENSITIVE_RE = /(pass(word|wd)?|secret|token|api[_-]?key|access[_-]?key|private[_-]?key|credential|auth(orization)?|cookie|session|cert|key)/i;
  function maskInspectToken(tok) {
    const s = String(tok);
    if (!INSPECT_SENSITIVE_RE.test(s)) return s;
    const eq = s.indexOf("=");
    // key=value 形态保留键名、掩去值；其余整段掩掉
    if (eq > 0 && !/\s/.test(s.slice(0, eq))) return s.slice(0, eq + 1) + "******";
    return "******";
  }
  function maskInspectLabels(map) {
    const out = {};
    for (const [k, v] of Object.entries(map || {})) {
      out[k] = INSPECT_SENSITIVE_RE.test(k) ? "******" : String(v);
    }
    return out;
  }
  async function extractMcpInspect(imageRef) {
    try {
      const { stdout } = await execFileHidden(
        "docker", ["inspect", "--format", "{{json .Config}}", imageRef],
        { timeout: 15000, maxBuffer: MAX_BUFFER },
      );
      const cfg = JSON.parse(String(stdout).trim() || "{}");
      const insp = {};
      if (cfg.Labels && Object.keys(cfg.Labels).length) insp.labels = maskInspectLabels(cfg.Labels);
      if (cfg.ExposedPorts) insp.exposed_ports = Object.keys(cfg.ExposedPorts);
      if (Array.isArray(cfg.Entrypoint) && cfg.Entrypoint.length) insp.entrypoint = cfg.Entrypoint.map(maskInspectToken);
      if (Array.isArray(cfg.Cmd) && cfg.Cmd.length) insp.cmd = cfg.Cmd.map(maskInspectToken);
      if (cfg.WorkingDir) insp.working_dir = cfg.WorkingDir;
      // 注意：绝不携带 cfg.Env
      return Object.keys(insp).length ? insp : null;
    } catch (_) {
      return null;
    }
  }
  // 懒回填：功能上线前已部署成功的记录没有镜像元数据，详情页首次访问时补提取一次
  async function ensureMcpInspect(s) {
    const meta = parseMeta(s);
    if (meta.deploy_status !== "deployed" || meta.mcp_inspect) return {};
    const image = meta.deployed_image || meta.recovery_image || meta.internal_ref || meta.image_ref;
    if (!image) return {};
    const insp = await extractMcpInspect(image);
    if (insp) {
      patchMeta(s.id, { mcp_inspect: insp });
      return { mcp_inspect: insp };
    }
    return {};
  }

  // MCP 源码包 README + 文件树懒回填：功能上线前审批的源码提交没有提取过，
  // 详情页首次访问时补提取一次并落 meta。mcp_readme_inspected 存提取规则版本号，
  // 规则升级后旧记录会自动用新规则重提一次。
  // v3：新增文件树提取（mcp_tree），供「代码」标签页展示 zip 包内文件。
  const MCP_README_INSPECT_VERSION = 3;

  async function ensureMcpReadme(s) {
    const meta = parseMeta(s);
    if (meta.source_type !== "source" || !meta.artifact_key) return {};
    if (meta.mcp_readme_inspected === MCP_README_INSPECT_VERSION) {
      return {
        mcp_readme: meta.mcp_readme || null,
        mcp_readme_name: meta.mcp_readme_name || null,
        mcp_tree: meta.mcp_tree || null,
      };
    }
    const insp = await inspectSkillPackage(meta.artifact_key).catch(() => null);
    const patch = {
      mcp_readme_inspected: MCP_README_INSPECT_VERSION,
      mcp_readme: (insp && insp.readme) || null,
      mcp_readme_name: (insp && insp.readme_name) || null,
      mcp_tree: insp && insp.tree ? insp.tree.slice(0, MCP_TREE_MAX) : null,
      mcp_file_count: insp ? insp.file_count : null,
    };
    patchMeta(s.id, patch);
    return {
      mcp_readme: patch.mcp_readme,
      mcp_readme_name: patch.mcp_readme_name,
      mcp_tree: patch.mcp_tree,
      mcp_file_count: patch.mcp_file_count,
    };
  }

  // 单个 mcp 详情（供 /mcp/[ref] 详情页）
  app.get("/mcp/:id", async (req, res) => {
    const s = db.prepare("SELECT * FROM submissions WHERE id=?").get(req.params.id);
    if (s && !canAccessSubmission(parseMeta(s), actorFromReq(req))) {
      return res.status(403).json({ error: "你没有权限查看该 MCP（未获管理员授权）" });
    }
    if (!s) {
      for (const m of LIVE_MCPS) {
        const ep = await discoverThvEndpoint(m.item_ref);
        if (ep) m.endpoint = ep;
      }
      const live = LIVE_MCPS.find((m) => m.id === req.params.id);
      if (live) {
        const calls = db.prepare(
          "SELECT COUNT(*) c FROM metric_events WHERE item_type='mcp' AND event='call' AND item_ref=?"
        ).get(live.id);
        const favs = db.prepare(
          "SELECT COUNT(*) c FROM favorites WHERE item_type='mcp' AND item_ref=?"
        ).get(live.id);
        const healthy = live.endpoint
          ? await probeMcpEndpoint(live.endpoint)
          : undefined;
        return res.json({
          ...live,
          healthy,
          public_endpoint: healthy
            ? publicEndpointFor(live.item_ref, live.endpoint, req)
            : undefined,
          mcp_headers: healthy ? mcpAuthHeadersFor(live.item_ref) : undefined,
          call_count: calls ? calls.c : 0,
          favorite_count: favs ? favs.c : 0,
          created_at: live.created_at || new Date().toISOString(),
        });
      }
      return res.status(404).json({ error: "mcp 不存在" });
    }
    const calls = db.prepare(
      "SELECT COUNT(*) c FROM metric_events WHERE item_type='mcp' AND event='call' AND item_ref=?"
    ).get(s.id);
    const favs = db.prepare(
      "SELECT COUNT(*) c FROM favorites WHERE item_type='mcp' AND item_ref=?"
    ).get(s.id);
    const row = mapMcpRow(s, { [s.id]: calls.c }, { [s.id]: favs.c });
    // 源码包 README（懒回填：历史提交首次访问时补提取一次，之后读 meta）
    Object.assign(row, await ensureMcpReadme(s));
    // 镜像元数据（懒回填：已部署但未提取过的记录首次访问时补一次）
    Object.assign(row, await ensureMcpInspect(s));
    // 部署时 thv list 报告的内部端口可能不可达；详情页返回前重新动态发现 ingress 端口。
    // 实例运行时缓存（SWR）：命中直接用；miss 时 rebuild 默认开启（保留"访问触发自愈"语义）
    let rt = rtCache.get(s.id);
    if (!rt) {
      rt = await rtFetchSingleFlight(s.id, s);
    } else {
      const age = Date.now() - rt.ts;
      const ttl = rt.failed ? RT_FAIL_MS : RT_FRESH_MS;
      if (age > ttl && !rtInflight.has(s.id)) rtFetchSingleFlight(s.id, s);
    }
    if (rt.endpoint) row.endpoint = rt.endpoint;
    // 只有真的跑起来了才给对外地址，否则用户复制过去是个连不通的空壳
    if (row.endpoint) {
      row.healthy = rt.healthy;
      if (row.healthy) {
        row.public_endpoint = publicEndpointFor(
          parseMeta(s).workload_name || workloadNameFor(s.id),
          row.endpoint,
          req,
        );
        const { headers: actorTokenHeaders, tokenRequired } = mcpHeadersForActor(s, actorFromReq(req));
        row.mcp_headers = actorTokenHeaders;
        if (tokenRequired) row.mcp_token_required = true;
      }
    }
    res.json(row);
  });

  // 源码包单文件内容预览（servePackageFile 共享实现留在 server.js，经 ctx 注入）
  app.get("/mcp/:id/file", async (req, res) => {
    const s = db.prepare("SELECT * FROM submissions WHERE id=?").get(req.params.id);
    if (!s) return res.status(404).json({ error: "mcp 不存在" });
    if (!canAccessSubmission(parseMeta(s), actorFromReq(req))) {
      return res.status(403).json({ error: "你没有权限查看该 MCP（未获管理员授权）" });
    }
    await servePackageFile(req, res, s);
  });

  // 真实 MCP 工具清单：按 id 找到运行中实例，调用 tools/list 返回真实能力。
  app.get("/mcp/:id/tools", async (req, res) => {
    const id = req.params.id;
    const cached = toolsCache.get(id);
    if (cached) {
      const age = Date.now() - cached.ts;
      const ttl = cached.failed ? TOOLS_FAIL_MS : TOOLS_FRESH_MS;
      // 过期不阻塞：立即回旧值，后台单飞刷新（已有刷新在跑则不重复发起）
      if (age > ttl && !toolsInflight.has(id)) toolsFetchSingleFlight(id);
      return res.json(
        req.query.debug === "1"
          ? { ...cached.result, debug: { cached: true, ageMs: age } }
          : cached.result,
      );
    }
    const r = await toolsFetchSingleFlight(id);
    return res.json(
      req.query.debug === "1" ? { ...r, debug: { cached: false } } : r,
    );
  });

  // 真实 MCP 调用：初始化连接 -> 列出工具 / 调用工具，返回真实结果。
  // body: { ref?, endpoint?, tool?, args?, actor_id? }
  //   - ref 命中 LIVE_ENDPOINTS 或服务名即 URL 时自动解析端点；
  //   - 也可直接传 endpoint 显式指定；
  //   - 不传 tool 返回 tools/list，传 tool 返回 tools/call 结果。
  app.post("/mcp/call", async (req, res) => {
    const { ref, endpoint, tool, args, actor_id } = req.body || {};
    let ep = null;
    // 1) 对平台已提交的 MCP，优先按 workload 动态发现当前 ingress 端口。
    //    不能信任前端传来的 endpoint，因为 thv list 在部署时报告的是内部端口，浏览器访问不到。
    let s = null;
    if (ref) {
      s = db.prepare("SELECT * FROM submissions WHERE id=? OR payload_ref=?").get(ref, ref);
      if (!s) {
        // ref 是 group_key：回落该组最新已上架版本（激活指针已废弃）
        s = db.prepare(
          "SELECT * FROM submissions WHERE status='approved' AND (meta LIKE ? OR payload_ref=?) ORDER BY created_at DESC"
        ).all(`%"group_key":"${ref}"%`, ref)
         .find((row) => isOnShelf(parseMeta(row)));
      }
    }
    if (s) {
      // 可见性校验：restricted 条目仅对被授权的成员/组与管理员开放调用
      if (!canAccessSubmission(parseMeta(s), actorFromReq(req))) {
        return res.status(403).json({ error: "你没有权限调用该 MCP（未获管理员授权）" });
      }
      ep = rewriteForWsl2(await discoverIngressForSubmission(s));
    }
    // 2) 未命中 submission（如 LIVE_MCPS / Registry Server 条目）按 ref/endpoint 解析
    if (!ep && ref) {
      ep = rewriteForWsl2(await resolveEndpoint(ref, endpoint));
    }
    // 3) 兜底：直接用显式 endpoint
    if (!ep && endpoint) {
      ep = rewriteForWsl2(endpoint);
    }
    if (!ep) return res.status(404).json({ error: "未找到该 MCP 的可调用端点（可能未在平台运行）" });
    if (!(await probeMcpEndpoint(ep))) {
      return res.status(502).json({
        error: "MCP 端点不可达",
        detail: `无法连接到 ${ep}，请确认 ToolHive MCP server 正在运行且端口可访问`,
      });
    }
    try {
      // 平台代调同样自动携带应用自身的 API Key（用户无需也不应知道应用凭证）
      const result = await mcpCallAuthed(ep, { tool, args }, s ? parseMeta(s) : {});
      // 仅在真正执行了某个工具时才记一次调用指标，保持统计语义
      if (tool) {
        db.prepare("INSERT INTO metric_events VALUES(?,?,?,?,?,?)")
          .run("ev_" + Date.now() + "_" + Math.floor(Math.random() * 1000),
            "mcp", ref || ep, "call", actor_id || "", new Date().toISOString());
      }
      res.json({ ok: true, endpoint: ep, ...result });
    } catch (e) {
      res.status(502).json({ error: "调用 MCP 失败", detail: e.message });
    }
  });

  // 轮换代理访问令牌（仅管理员，仅 MCP）：生成新 mcp_token 覆盖旧值。
  // 旧 Token 立即作废——所有已复制到客户端的接入配置会 401，需重新复制配置；
  // 其他 MCP 不受影响（token 本就是 per-MCP 一把）。写审计轨迹备查。
  // 双轨制说明（2026-10-13）：本路由轮换的是「包级」token，全员失效；
  // 按成员轮换走 POST /submissions/:id/member-tokens（只影响单个成员）。
  app.post("/submissions/:id/rotate-token", (req, res) => {
    const actor = actorFromReq(req);
    if (!actor.admin) return res.status(403).json({ error: "仅管理员可轮换 Token" });
    const { id } = req.params;
    const sub = db.prepare("SELECT * FROM submissions WHERE id=?").get(id);
    if (!sub) return res.status(404).json({ error: "submission 不存在" });
    if (sub.type !== "mcp") return res.status(400).json({ error: "只有 MCP 有代理 Token" });
    const token = crypto.randomBytes(16).toString("hex");
    patchMeta(id, { mcp_token: token });
    audit(req, "token_rotate", "mcp", id, { scope: "package" });
    res.json({ ok: true, id });
  });

  // ---- 成员级代理 Token 管理（双轨制，仅管理员，仅 MCP）----
  // 成员 token 与包级 token 并行有效：签发/轮换/吊销成员 token 只影响该成员的接入配置。
  // member 必须在条目可见范围 users（按邮箱授权名单）内——D2 决策：groups 授权不参与成员 token。

  // 列表：可见范围 users × 各自签发状态（token 一并返回，管理员可直接复制成员专属配置）。
  // 2026-10-14：任何模式都返回名单（mode=all 的名单 = 已自助签发/管理员添加的成员，
  // 名单在切模式时保留）。名单读取/归一化统一走 lib/member-tokens.js。
  app.get("/submissions/:id/member-tokens", (req, res) => {
    const actor = actorFromReq(req);
    if (!actor.admin) return res.status(403).json({ error: "仅管理员可查看成员 Token" });
    const sub = db.prepare("SELECT * FROM submissions WHERE id=?").get(req.params.id);
    if (!sub) return res.status(404).json({ error: "submission 不存在" });
    if (sub.type !== "mcp") return res.status(400).json({ error: "只有 MCP 有代理 Token" });
    const meta = parseMeta(sub);
    const rv = readRawVisibility(meta);
    const rows = db
      .prepare("SELECT member, token, created_at, rotated_at FROM mcp_member_tokens WHERE submission_id=?")
      .all(sub.id);
    const byEmail = {};
    rows.forEach((r) => { byEmail[r.member] = r; });
    const members = readUsers(meta).map((u) => ({
      member: u,
      token: byEmail[u] ? byEmail[u].token : null,
      created_at: byEmail[u] ? byEmail[u].created_at : null,
      rotated_at: byEmail[u] ? byEmail[u].rotated_at : null,
    }));
    res.json({ ok: true, mode: rv.mode, members });
  });

  // 签发 / 轮换（body: {member}）。已签发 → 轮换（旧 token 立即作废）；未签发 → 签发。
  app.post("/submissions/:id/member-tokens", (req, res) => {
    const actor = actorFromReq(req);
    if (!actor.admin) return res.status(403).json({ error: "仅管理员可签发成员 Token" });
    const sub = db.prepare("SELECT * FROM submissions WHERE id=?").get(req.params.id);
    if (!sub) return res.status(404).json({ error: "submission 不存在" });
    if (sub.type !== "mcp") return res.status(400).json({ error: "只有 MCP 有代理 Token" });
    const member = normalizeEmail((req.body && req.body.member) || "");
    if (!member) return res.status(400).json({ error: "缺少 member（成员邮箱）" });
    // 管理员签发：名单内直接走 memberTokenAllowed；名单外（mode=all 下给新成员代签）
    // 自动把成员并入 users 再签发（audit 记 visibility_adopt_member）。
    const meta = parseMeta(sub);
    if (!memberTokenAllowed(meta, member)) {
      if (!actor.admin) {
        return res.status(422).json({
          error: "该成员不在条目可见范围（按邮箱授权名单）内，请先在「可见范围」中添加",
        });
      }
      const { visibility, changed } = visibilityWithMember(meta, member);
      patchMeta(sub.id, { visibility, visibility_configured: true });
      if (changed) audit(req, "visibility_adopt_member", "mcp", sub.id, { member });
    }
    const { token, action } = issueOrRotateToken(db, sub.id, member, new Date().toISOString());
    audit(req, action === "rotated" ? "token_rotate" : "token_issue", "mcp", sub.id, { scope: "member", member });
    res.json({ ok: true, id: sub.id, member, token });
  });

  // 批量签发 / 轮换（P1，2026-10-14，body: {members:[邮箱,...]}）：
  // 逐个走与单签完全相同的校验（memberTokenAllowed）与入库逻辑，名单外成员跳过不中断整批。
  // 用途：mode=all / groups 条目收编 restricted+users 后一次性为全员签发（收编动作见下方 merge-users）。
  app.post("/submissions/:id/member-tokens/batch", (req, res) => {
    const actor = actorFromReq(req);
    if (!actor.admin) return res.status(403).json({ error: "仅管理员可批量签发成员 Token" });
    const sub = db.prepare("SELECT * FROM submissions WHERE id=?").get(req.params.id);
    if (!sub) return res.status(404).json({ error: "submission 不存在" });
    if (sub.type !== "mcp") return res.status(400).json({ error: "只有 MCP 有代理 Token" });
    const raw = Array.isArray(req.body && req.body.members) ? req.body.members : [];
    // 归一化（与 visibility 名单同规则：小写去空白）+ 去重；上限 500 防误传全通讯录拖垮请求
    const members = normalizeEmails(raw);
    if (!members.length) return res.status(400).json({ error: "缺少 members（成员邮箱数组）" });
    if (members.length > 500) return res.status(400).json({ error: "单批最多 500 个成员" });
    const meta = parseMeta(sub);
    const now = new Date().toISOString();
    const results = members.map((member) => {
      if (!memberTokenAllowed(meta, member)) {
        return { member, ok: false, reason: "not_in_visibility" };
      }
      const { token, action } = issueOrRotateToken(db, sub.id, member, now);
      audit(req, action === "rotated" ? "token_rotate" : "token_issue", "mcp", sub.id, { scope: "member", member });
      return { member, ok: true, action, token };
    });
    const okCount = results.filter((r) => r.ok).length;
    audit(req, "token_batch", "mcp", sub.id, {
      scope: "member-batch", total: members.length, issued_rotated: okCount,
      skipped: members.length - okCount,
    });
    res.json({ ok: true, id: sub.id, total: members.length, issued: okCount, results });
  });

  // 可见范围名单合并（P1，IdP 无关）：把外部来源整理好的成员邮箱合并进 visibility.users。
  // 用途：① mode=all 条目首次合并即自动转为 restricted（首次即完成「收编」）；
  //       ② restricted+groups 条目把组展开后的邮箱并入 users（组员从此可签发成员 token）。
  // 注意：不做 IdP 自动拉取——组成员数据在 Casdoor 且其即将退役，自动同步随 P2/Authentik
  // 一并落地；本接口只接收已整理好的名单（企微通讯录导出 / 管理员手工整理均可）。
  // drop_groups=true 时同时清空 groups（组授权改名单制的收尾动作，防止组员继续共用包级 token 的歧义）。
  app.post("/submissions/:id/visibility/merge-users", (req, res) => {
    const actor = actorFromReq(req);
    if (!actor.admin) return res.status(403).json({ error: "仅管理员可合并可见范围名单" });
    const sub = db.prepare("SELECT * FROM submissions WHERE id=?").get(req.params.id);
    if (!sub) return res.status(404).json({ error: "submission 不存在" });
    const raw = Array.isArray(req.body && req.body.users) ? req.body.users : [];
    const incoming = normalizeEmails(raw);
    if (!incoming.length) return res.status(400).json({ error: "缺少 users（成员邮箱数组）" });
    if (incoming.length > 5000) return res.status(400).json({ error: "单次最多合并 5000 个邮箱" });
    const meta = parseMeta(sub);
    // 基线名单读原始 visibility（readRawVisibility）——parseVisibility 在 mode=all 时
    // 返回空名单，用它做基线会把保留的名单清掉（2026-10-14 自检整改时修复的潜伏 bug）。
    const rv = readRawVisibility(meta);
    const merged = [...new Set([...rv.users, ...incoming])].sort();
    const added = merged.filter((u) => !rv.users.includes(u)).length;
    const dropGroups = Boolean(req.body && req.body.drop_groups);
    const nextGroups = dropGroups ? [] : rv.groups;
    patchMeta(sub.id, {
      visibility: { mode: "restricted", users: merged, groups: nextGroups },
      visibility_configured: true, // 管理员显式配置过可见范围 → 上架（isOnShelf 语义）
    });
    audit(req, "visibility_merge_users", sub.type, sub.id, {
      before: { mode: rv.mode, users: rv.users.length, groups: rv.groups },
      added, total: merged.length, drop_groups: dropGroups,
    });
    res.json({
      ok: true, id: sub.id, mode: "restricted",
      added, total: merged.length, groups: nextGroups,
    });
  });

  // 自助签发（2026-10-14，D2 修订：groups 在「签发时」参与资格判定，调用层仍凭个人 token）。
  // 登录用户为自己签发/轮换成员 token，资格走 canAccessSubmission 单一入口：
  //   mode=all → 任何登录用户；restricted+users → 名单内；restricted+groups → 组命中；
  //   未上架（visibility_configured=false）仅管理员可见，普通用户天然 403。
  // 签发即把成员并入 visibility.users（名单自增长，audit 留痕）——proxy 双轨校验零改动，
  // memberTokenAllowed（member ∈ users）天然放行；组资格只在签发时验证一次，
  // 调岗后 token 仍有效的问题由 P2（IDM 同步 / token 有效期）兜底。
  app.post("/submissions/:id/my-member-token", (req, res) => {
    const actor = actorFromReq(req);
    const member = String(actor.email || "").toLowerCase().trim();
    if (!member) return res.status(401).json({ error: "未识别到登录身份" });
    const sub = db.prepare("SELECT * FROM submissions WHERE id=?").get(req.params.id);
    if (!sub) return res.status(404).json({ error: "submission 不存在" });
    if (sub.type !== "mcp") return res.status(400).json({ error: "只有 MCP 有代理 Token" });
    const meta = parseMeta(sub);
    if (!actor.admin && !canAccessSubmission(meta, actor)) {
      audit(req, "token_selfissue_denied", "mcp", sub.id, { member }, "denied");
      return res.status(403).json({ error: "你不在该条目的可见范围内，无法自助签发" });
    }
    const now = new Date().toISOString();
    const { token, action } = issueOrRotateToken(db, sub.id, member, now);
    audit(req, action === "rotated" ? "token_rotate" : "token_issue", "mcp", sub.id, { scope: "member", member, self_service: true });
    // 名单自增长：把签发者并入 users（幂等；mode=all 下名单保留，切回受限即生效）。
    // 合并基准统一走 lib/member-tokens.js（读原始 meta.visibility，勿用 parseVisibility）。
    const { visibility, changed } = visibilityWithMember(meta, member);
    let adopted = false;
    if (changed) {
      patchMeta(sub.id, { visibility, visibility_configured: true });
      audit(req, "visibility_adopt_member", "mcp", sub.id, { member });
      adopted = true;
    }
    // 顺带返回接入配置（等价 member-token-config，省一次往返）
    const fresh = parseMeta(db.prepare("SELECT * FROM submissions WHERE id=?").get(sub.id));
    const endpoint = fresh.endpoint || null;
    res.json({
      ok: true, id: sub.id, member, token, adopted,
      url: endpoint ? publicEndpointFor(fresh.workload_name || workloadNameFor(sub.id), endpoint, req) : null,
      headers: { Authorization: `Bearer ${token}` },
    });
  });

  // 吊销（成员 token 立即作废；该成员接入配置 401，需管理员重新签发）
  app.delete("/submissions/:id/member-tokens/:member", (req, res) => {
    const actor = actorFromReq(req);
    if (!actor.admin) return res.status(403).json({ error: "仅管理员可吊销成员 Token" });
    const sub = db.prepare("SELECT * FROM submissions WHERE id=?").get(req.params.id);
    if (!sub) return res.status(404).json({ error: "submission 不存在" });
    if (sub.type !== "mcp") return res.status(400).json({ error: "只有 MCP 有代理 Token" });
    const member = String(req.params.member || "").toLowerCase().trim();
    const info = db
      .prepare("DELETE FROM mcp_member_tokens WHERE submission_id=? AND member=?")
      .run(sub.id, member);
    if (info.changes > 0) {
      audit(req, "token_revoke", "mcp", sub.id, { scope: "member", member });
    }
    res.json({ ok: true, id: sub.id, member, revoked: info.changes > 0 });
  });

  // 成员专属接入配置（仅管理员）：publicEndpointFor + 该成员 token 的 Authorization 头，
  // 供「Token 管理」弹窗一键复制，免去前端自行拼对外地址。
  app.get("/submissions/:id/member-token-config", (req, res) => {
    const actor = actorFromReq(req);
    if (!actor.admin) return res.status(403).json({ error: "仅管理员可获取成员接入配置" });
    const sub = db.prepare("SELECT * FROM submissions WHERE id=?").get(req.params.id);
    if (!sub) return res.status(404).json({ error: "submission 不存在" });
    if (sub.type !== "mcp") return res.status(400).json({ error: "只有 MCP 有代理 Token" });
    const member = String(req.query.member || "").toLowerCase().trim();
    const row = db
      .prepare("SELECT token FROM mcp_member_tokens WHERE submission_id=? AND member=?")
      .get(sub.id, member);
    if (!row) return res.status(404).json({ error: "该成员尚未签发 Token" });
    const meta = parseMeta(sub);
    const endpoint = meta.endpoint || null;
    if (!endpoint) return res.json({ ok: true, url: null, headers: null });
    return res.json({
      ok: true,
      url: publicEndpointFor(meta.workload_name || workloadNameFor(sub.id), endpoint, req),
      headers: { Authorization: `Bearer ${row.token}` },
    });
  });

  // 供 server.js 的 deploy/undeploy 在部署事件时双清两层缓存；
  // extractMcpInspect 供 services/deploy 在部署成功后提取镜像元数据（详情页「代码」标签）
  return {
    invalidate(id) {
      toolsCache.delete(id);
      rtCache.delete(id);
    },
    extractMcpInspect,
  };
};

// routes/submission-upload.js —— 上传/制品入口域（2026-10-08 自 submissions.js 拆出第五刀）
// 覆盖：镜像 tar 上传 / Skill 制品上传 / 源码包上传 / 源码包直接提交，及其共用的
//   防滥用三件套（身份二选一 + 固定窗口限流 + 体积上限）。
// 依赖经 ctx 注入，与 submissions.js 同一份装配块（见 server.js 末尾），语义原样迁出。
"use strict";
const path = require("node:path");
const fs = require("node:fs");
const crypto = require("node:crypto");
const express = require("express");
const createWindowRateLimiter = require("../lib/rate-limit");

module.exports = function registerSubmissionUploadRoutes(app, ctx) {
  const {
    db, parseMeta, actorFromReq, audit, deniedThrottled,
    objStore, stagingKey, sanitizeUploadName, ensureGroupMeta, runSubmissionScans,
    INTERNAL_PROXY_TOKEN, RATE_WINDOW_MS,
    tarListFile, MAX_TAR_UPLOAD_MB, MAX_TAR_UPLOAD_BYTES,
  } = ctx;

  // ---- 上传防滥用（身份 + 限流 + 体积上限）----
  // 上传口（/upload、/upload/tar、/upload/source、/submissions/source）共用：
  //   · 身份：二选一 —— 带内部令牌（前端 Next 服务端转发）或带用户身份 header（网关注入）
  //   · 限流：每身份每小时 UPLOAD_RATE_MAX 次（复用提交防刷的窗口）
  //   · 体积：UPLOAD_MAX_MB（默认 50MB，真实制品远小于此，100MB 是被滥用空间）
  const UPLOAD_MAX_MB = Number(process.env.UPLOAD_MAX_MB || 50);
  const UPLOAD_RATE_MAX = Number(process.env.UPLOAD_RATE_MAX || 10);
  // 固定窗口限流器已抽至 lib/rate-limit.js（now 可注入，可单测），语义与原内联实现一致
  const uploadLimiter = createWindowRateLimiter({ windowMs: RATE_WINDOW_MS, max: UPLOAD_RATE_MAX });
  function uploadAllowed(actor) {
    return uploadLimiter.allowed(actor);
  }
  // 鉴权：内部令牌（Next 服务端转发）或用户身份（网关注入的 x-actor-email）满足其一
  function uploadAuthOk(req) {
    if (req.headers["x-internal-proxy"] === INTERNAL_PROXY_TOKEN) return "internal";
    const actor = actorFromReq(req);
    if (actor.email) return actor.email;
    return null;
  }

  // 接收 docker save 镜像包（.tar/.tar.gz），流式落盘 staging 并校验魔数与 manifest。
  // 2026-09-12 自 server.js 迁入（原留守在 server.js 但调用的 uploadAuthOk/uploadAllowed
  // 已随第四刀迁至本模块 → 任何对该路由的访问都会 ReferenceError 崩溃进程）。
  app.post("/upload/tar", (req, res) => {
    const who = uploadAuthOk(req);
    if (!who) return res.status(401).json({ error: "upload/tar 需要登录身份（请经平台前端上传）" });
    if (!uploadAllowed(who)) return res.status(429).json({ error: "上传过于频繁，请稍后再试" });
    const filename = sanitizeUploadName(req.query.name);
    const key = stagingKey("mcp", filename);
    const fp = path.join(ctx.TAR_ROOT, key);
    fs.mkdirSync(path.dirname(fp), { recursive: true });
    const hash = crypto.createHash("sha256");
    let size = 0;
    let aborted = false;
    const ws = fs.createWriteStream(fp);
    const fail = (code, msg) => {
      if (aborted) return;
      aborted = true;
      try { ws.destroy(); } catch (_) {} // 上传中止后 ws 可能已断开，destroy 幂等
      fs.unlink(fp, () => {});
      if (!res.headersSent) res.status(code).json({ error: msg });
    };
    req.on("data", (chunk) => {
      if (aborted) return;
      size += chunk.length;
      if (size > MAX_TAR_UPLOAD_BYTES) {
        return fail(413, `镜像包体积超过上限 ${MAX_TAR_UPLOAD_MB}MB，请精简镜像或改用 ghcr 地址提交`);
      }
      hash.update(chunk);
      ws.write(chunk, (e) => { if (e) fail(500, "写盘失败: " + e.message); });
    });
    req.on("error", (e) => fail(400, "上传中断: " + e.message));
    ws.on("error", (e) => fail(500, "写盘失败: " + e.message));
    req.on("end", () => {
      if (aborted) return;
      ws.end(async () => {
        try {
          const fd = fs.openSync(fp, "r");
          const head = Buffer.alloc(262);
          const n = fs.readSync(fd, head, 0, 262, 0);
          fs.closeSync(fd);
          const isGzip = head[0] === 0x1f && head[1] === 0x8b;
          const isTar = n >= 262 && head.toString("ascii", 257, 262) === "ustar";
          if (!isGzip && !isTar) {
            return fail(400, "文件不是合法的 docker save 镜像包（需 .tar 或 .tar.gz）");
          }
          // 魔数通过还不够：源码压缩包也是合法 tar。docker save 产物在 tar 根目录
          // 必然包含 manifest.json（或 OCI 的 index.json）与 repositories。缺失即可判定
          // 不是镜像包，提前在上传阶段拦截，避免到部署时才报「缺少 image_ref」。
          // 解析失败（超大镜像等）则放行，交由审批后的 docker load 兜底校验。
          const tf = await tarListFile(fp);
          if (!tf.err) {
            const names = tf.stdout.split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
            const looksLikeImage = names.some((nm) =>
              /^(manifest\.json|repositories|index\.json|oci-layout)$/.test(nm),
            );
            if (!looksLikeImage) {
              return fail(400, "文件不是合法的 docker save 镜像包（根目录缺少 manifest.json / repositories）。请使用 `docker save 镜像名:tag -o 文件.tar` 导出后上传，不要上传源码或普通压缩包。");
            }
          }
        } catch (e) {
          return fail(400, "校验失败: " + (e && e.message));
        }
        if (!res.headersSent) res.json({ key, sha256: hash.digest("hex"), size });
      });
    });
  });

  // 接收原始二进制（Skill 包 .tar.gz），落入 ObjectStore，返回内部 key + sha256。
  // 制品来源 = 提交者本人，平台存盘后生成 artifact_key 交回前端，提交时写入 meta。
  app.post("/upload", express.raw({ type: "*/*", limit: `${UPLOAD_MAX_MB}mb` }), async (req, res) => {
    try {
      const who = uploadAuthOk(req);
      if (!who) {
        if (deniedThrottled("upload:" + (req.socket.remoteAddress || ""))) {
          audit(req, "upload_denied", "skill", "", { reason: "unauthenticated" }, "denied");
        }
        return res.status(401).json({ error: "upload 需要登录身份（请经平台前端上传）" });
      }
      if (!uploadAllowed(who)) return res.status(429).json({ error: "上传过于频繁，请稍后再试" });
      if (!Buffer.isBuffer(req.body) || req.body.length === 0)
        return res.status(400).json({ error: "空文件" });
      const filename = req.query.name || "artifact_" + Date.now() + ".tar.gz";
      const key = stagingKey("skill", filename);
      const info = await objStore.put(key, req.body);
      res.json({ key: info.key, sha256: info.sha256, size: info.size });
    } catch (e) {
      res.status(500).json({ error: String((e && e.message) || e) });
    }
  });

  // 源码包上传（zip/tar.gz，MCP 自动构建用）。上限 20MB；与镜像包同等身份门。
  app.post("/upload/source", express.raw({ type: "*/*", limit: "20mb" }), (req, res) => {
    try {
      const who = uploadAuthOk(req);
      if (!who) {
        if (deniedThrottled("upload:" + (req.socket.remoteAddress || ""))) {
          audit(req, "upload_denied", "mcp", "", { reason: "unauthenticated" }, "denied");
        }
        return res.status(401).json({ error: "upload/source 需要登录身份（请经平台前端上传）" });
      }
      if (!uploadAllowed(who)) return res.status(429).json({ error: "上传过于频繁，请稍后再试" });
      if (!Buffer.isBuffer(req.body) || req.body.length === 0)
        return res.status(400).json({ error: "空文件" });
      const filename = sanitizeUploadName(req.query.name || "source.zip");
      if (!/\.(zip|tar\.gz|tgz)$/i.test(filename))
        return res.status(400).json({ error: "源码包仅支持 .zip / .tar.gz / .tgz" });
      const key = stagingKey("src", filename);
      objStore.put(key, req.body);
      audit(req, "upload", "mcp-source", "", { filename, size: req.body.length });
      res.json({ key, size: req.body.length });
    } catch (e) {
      res.status(500).json({ error: String((e && e.message) || e) });
    }
  });

  // 提交 MCP 源码包（自动构建）：与普通提交同一入口，meta.source_type="source" 时
  // 部署阶段先 buildSourceImage 构建本地镜像再 thv run。
  app.post("/submissions/source", express.raw({ type: "*/*", limit: "20mb" }), async (req, res) => {
    try {
      const who = uploadAuthOk(req);
      if (!who) return res.status(401).json({ error: "需要登录身份（请经平台前端提交）" });
      if (!uploadAllowed(who)) return res.status(429).json({ error: "提交过于频繁，请稍后再试" });
      if (!Buffer.isBuffer(req.body) || req.body.length === 0)
        return res.status(400).json({ error: "空文件" });
      const filename = sanitizeUploadName(req.query.name || "source.zip");
      if (!/\.(zip|tar\.gz|tgz)$/i.test(filename))
        return res.status(400).json({ error: "源码包仅支持 .zip / .tar.gz / .tgz" });
      const key = stagingKey("src", filename);
      objStore.put(key, req.body);

      // 提交者身份优先取真实邮箱（内部令牌通道 who=="internal" 时 fromReq 仍有 x-actor-email）
      const actor = actorFromReq(req);
      const user_id = String(actor.email || who || "anonymous");
      // 名称自 2026-09-30 起必填：缺失直接拒绝，不再回退文件名
      // （此前回退导致打包文件名里的日期/版本号原样变成条目显示名）
      if (!String(req.query.display_name || "").trim()) {
        return res.status(400).json({ error: "display_name（名称）为必填项" });
      }
      const name = String(req.query.display_name).trim().slice(0, 80);
      // 版本与产品引用：用户表单填了 payload_ref（产品名:版本号）就以其为准；
      // version 缺省时不写死 1.0.0——交由 ensureGroupMeta 从 payload_ref 自动提取
      // （此前前端把空 version 兜底成 "1.0.0" 传入，导致引用里的 :2.0.2 永远不被识别）。
      const userRef = String(req.query.payload_ref || "").trim();
      const version = String(req.query.version || "").trim();
      const id = "sub_" + Date.now();
      // 数据源声明（两段式豁免第 1 段，可选）：query 携带 JSON，解析/校验失败静默丢弃
      // （此时制品已收库，声明是可选项，不该因它 400 留孤儿制品；审批看不到声明自然不给豁免）
      let dataSource;
      try {
        dataSource = req.query.data_source ? JSON.parse(String(req.query.data_source)) : undefined;
      } catch (_) { dataSource = undefined; }
      const meta = {
        name,
        ...(version ? { version } : {}),
        source_type: "source",
        artifact_key: key,
        artifact_filename: filename,
        visibility: { mode: "restricted", users: [], groups: [] },
        visibility_configured: false,
      };
      if (dataSource && typeof dataSource === "object") {
        const dsType = String(dataSource.type || "none").trim();
        if (["none", "http_api", "database"].includes(dsType)) {
          meta.data_source = {
            type: dsType,
            targets: Array.isArray(dataSource.targets)
              ? dataSource.targets.map((t) => String(t).trim()).filter(Boolean).slice(0, 10)
              : [],
            note: String(dataSource.note || "").slice(0, 200),
          };
        }
      }
      const metaJson = JSON.stringify(meta);
      // payload_ref：用户表单填的产品引用（产品名:版本号）优先；未填则回落 zip 文件名
      // （剥掉压缩包扩展名，避免版本提取吃到 ".zip" 尾巴）
      const finalRef = userRef || filename.replace(/\.(zip|tar\.gz|tgz)$/i, "");
      db.prepare(`INSERT INTO submissions VALUES(?,?,?,?,?,?,?,?)`)
        .run(id, user_id, "mcp", finalRef, "pending", "pending", new Date().toISOString(), metaJson);
      ensureGroupMeta({ id, payload_ref: finalRef, meta: metaJson });
      runSubmissionScans(id, "mcp");
      audit(req, "submit", "mcp-source", id, { filename, size: req.body.length });
      res.json({ id, status: "pending" });
    } catch (e) {
      res.status(500).json({ error: String((e && e.message) || e) });
    }
  });
};

// routes/submissions.js —— Submissions 路由域：提交 / 列表 / 可见范围 / 来源分级 / 审批 /
//   部署 / 下线 / Registry 同步 / 多版本查询 / 生命周期状态 / 重跑扫描。
// （2026-10-08 拆分第五刀：上传域 → routes/submission-upload.js，.env 配置域 → routes/submission-env.js）
// 依赖经 ctx 注入；本模块采用「延迟装配」（在 server.js 末尾注册），
// 因为其依赖的常量（RATE_* / DUP_STATUSES / MCP_TREE_MAX / MCP_README_INSPECT_VERSION 等）
// 声明位置靠后，const 无提升——延迟到文件末尾装配可规避 TDZ。
"use strict";
const path = require("node:path");
const logger = require("../lib/logger");
const { resolveVisibilitySave } = require("../lib/visibility");

// README/文件树提取规则版本号（与 routes/mcp.js 各自独立持有一份，语义一致）
const MCP_README_INSPECT_VERSION = 3;

module.exports = function registerSubmissionsRoutes(app, ctx) {
  const {
    db, parseMeta, patchMeta, actorFromReq, audit,
    objStore, normName, promoteArtifact,
    ensureGroupMeta, ensureRegistryMeta, registryDelete, registryPublish,
    listGroupVersions, classifyRegistry, runSubmissionScans,
    deleteSubmissionSecrets, undeployMcp, deployMcp,
    canAccessSubmission, pickDisplayVersions, isOnShelf,
    validateSkillPackage, inspectSkillPackage,
    INTERNAL_REGISTRY, INTERNAL_ONLY, TRUSTED_REGISTRIES,
    RATE_WINDOW_MS, RATE_MAX, DUP_STATUSES, MAX_BUFFER,
    MCP_TREE_MAX,
    // 注意：MCP_README_INSPECT_VERSION 不从 ctx 解构——模块顶层已有同名 const(=3)，
    // 若在此解构会以 undefined 遮蔽它，破坏 README 懒回填的版本判断。
  } = ctx;

  // 提交（落暂存，status=pending）。meta 存放 name/description/download_url 等扩展字段。
  app.post("/submissions", async (req, res) => {
    const { user_id, type, payload_ref, meta } = req.body || {};
    if (!user_id || !type || !payload_ref)
      return res.status(400).json({ error: "user_id, type, payload_ref 必填" });
    // 名称自 2026-09-30 起必填（meta.name 缺失即拒绝，不再回退 payload_ref 显示）
    if (!meta || !String(meta.name || "").trim())
      return res.status(400).json({ error: "meta.name（名称）为必填项" });

    // 1) 限流：同用户窗口内提交数超限 → 429
    const since = new Date(Date.now() - RATE_WINDOW_MS).toISOString();
    const recent = db.prepare(
      "SELECT COUNT(*) c FROM submissions WHERE user_id=? AND created_at >= ?"
    ).get(user_id, since).c;
    if (recent >= RATE_MAX) {
      return res.status(429).json({
        error: "提交过于频繁，请稍后再试",
        retry_after_sec: Math.ceil(RATE_WINDOW_MS / 1000),
      });
    }

    // 2) 同用户去重：pending/approved 状态内，同 type +（同名 或 同 payload_ref）即视为重复
    // 注意：express.json 已把 meta 解析成对象，勿再 JSON.parse；可能是字符串（老调用方）则解析
    const rawMeta = req.body.meta;
    const m = rawMeta && typeof rawMeta !== "string"
      ? rawMeta
      : (typeof rawMeta === "string" ? (() => { try { return JSON.parse(rawMeta); } catch (_) { return {}; } })() : {});
    // 2.5) MCP 来源分级校验：
    //  - source_type=tar：用户上传的镜像包，受控可信，审批后部署（不强制推内网）
    //  - image_ref：命中档1 内网直通 / 档2 受信白名单留痕 / 档3 未知来源拦截
    if (type === "mcp") {
      if (m.source_type === "tar") {
        if (!m.artifact_key) {
          return res.status(400).json({ error: "tar 方式提交缺少 artifact_key（上传未成功）" });
        }
        m.registry_tier = 0; // 0 = 用户上传镜像包（受控可信源）
        m.source_registry = "user-upload";
        m.auto_mirror = false; // tar 不走内网镜像统一出口
      } else if (m.image_ref) {
        const cls = classifyRegistry(m.image_ref);
        if (!cls.allowed) {
          return res.status(400).json({
            error: "镜像来源未通过校验：" + cls.message,
            registry_tier: cls.tier,
            registry: cls.registry,
          });
        }
        // 留痕：记录来源分级与原始 registry，供审批与审计追溯
        m.registry_tier = cls.tier;
        m.source_registry = cls.registry;
        m.auto_mirror = m.auto_mirror === true || m.auto_mirror === "true" || m.auto_mirror === "1";
      } else {
        return res.status(400).json({
          error: "MCP 需提供 ghcr 镜像地址（image_ref）或上传镜像 tar 包（source_type=tar）",
        });
      }
    }
    if (type === "skill") {
      if (!m.artifact_key) {
        return res.status(400).json({ error: "Skill 需上传制品或填写文件位置" });
      }
      const validation = await validateSkillPackage(m.artifact_key);
      if (!validation.valid) {
        try { await objStore.del(m.artifact_key); } catch (_) {} // 制品可能已不存在，清理失败不掩盖校验失败的主错误
        return res.status(400).json({ error: "Skill 包不合规：" + validation.error });
      }
      // 以 SKILL.md 中的 name/description 为权威来源，覆盖表单输入，避免不一致
      m.name = validation.name;
      m.description = validation.description;
    }
    const nm = normName(m.name);
    const existing = db.prepare(
      "SELECT id, status, meta, payload_ref FROM submissions WHERE user_id=? AND type=? AND status IN (" +
      DUP_STATUSES.map(() => "?").join(",") + ")"
    ).all(user_id, type, ...DUP_STATUSES);
    const dup = existing.find((e) => {
      // 多版本场景：同名 + 不同版本号是合法的新版本（如 dws-skill:1.0.0 与 :1.1.0）。
      // 仅当 payload_ref 完全一致时才视为重复提交；这样既能防刷屏，又不阻断版本迭代。
      return e.payload_ref === payload_ref;
    });
    if (dup) {
      return res.status(409).json({
        error: "你已提交过同名/同引用的 " + type + "（当前状态：" + dup.status + "），请勿重复提交",
        existing_id: dup.id,
        existing_status: dup.status,
      });
    }

    // 数据源声明（两段式豁免第 1 段：提交者声明意图）。可选项：非法/缺失不阻断提交，
    // 规整失败直接丢弃——审批页看不到声明自然不会给豁免，安全默认不受影响。
    if (m.data_source !== undefined) {
      const ds = m.data_source && typeof m.data_source === "object" ? m.data_source : {};
      const dsType = String(ds.type || "none").trim();
      if (["none", "http_api", "database"].includes(dsType)) {
        m.data_source = {
          type: dsType,
          targets: Array.isArray(ds.targets)
            ? ds.targets.map((t) => String(t).trim()).filter(Boolean).slice(0, 10)
            : [],
          note: String(ds.note || "").slice(0, 200),
        };
      } else {
        delete m.data_source;
      }
    }

    // 默认可见范围：新提交默认未上线（visibility_configured=false），仅管理员在已发布管理可见。
    // 管理员审批后在「可见范围」里显式选择并保存 → visibility_configured=true → 才算上线，
    // 此后才对该条目解锁「部署」(MCP) / 对所选成员/组开放目录可见与下载(Skill)。
    // 提交者不感知；存量条目无此字段仍视为已上线（向后兼容）。
    if (!m.visibility) m.visibility = { mode: "restricted", users: [], groups: [] };
    if (typeof m.visibility_configured !== "boolean") m.visibility_configured = false;

    const id = "sub_" + Date.now();
    // 统一用解析后的 m 序列化，保证分级留痕字段（registry_tier 等）一定落库
    const metaJson = rawMeta ? JSON.stringify(m) : null;
    db.prepare(`INSERT INTO submissions VALUES(?,?,?,?,?,?,?,?)`)
      .run(id, user_id, type, payload_ref, "pending", "pending", new Date().toISOString(), metaJson);
    // 派生 group_key / version 并写回 meta，便于后续多版本管理
    ensureGroupMeta({ id, payload_ref, meta: metaJson });
    // 安全扫描（Trivy + Skill 提示词注入规则）异步执行，结果回写 meta.trivy / meta.prompt_scan
    runSubmissionScans(id, type);
    audit(req, "submit", type, id, { payload_ref, source: m.source_type || "unknown" });
    res.json({ id, status: "pending" });
  });

  // 待审列表。权限规则：管理员看全部；已登录普通用户只看自己的提交；匿名调用返回空。
  app.get("/submissions", (req, res) => {
    const actor = actorFromReq(req);
    const rows = db.prepare("SELECT * FROM submissions ORDER BY created_at DESC").all();
    let visible = rows;
    if (!actor.admin) {
      if (!actor.email) {
        visible = [];
      } else {
        visible = rows.filter((r) => String(r.user_id || "").toLowerCase() === actor.email);
      }
    }
    res.json(visible);
  });

  // 管理员设置条目可见范围（发布时决定哪些成员/组可查看/下载/调用）。
  // 2026-10-14 起名单与模式解耦（resolveVisibilitySave）：mode=all 的保存不动名单，
  // restricted 缺省保留现值、显式提供才覆盖，空名单 + 已有成员 token 自动并入成员邮箱——
  // 防止 UI 弹窗保存把收编（merge-users）写入的名单覆盖丢失。
  app.post("/submissions/:id/visibility", (req, res) => {
    const actor = actorFromReq(req);
    if (!actor.admin)
      return res.status(403).json({ error: "仅管理员可设置可见范围" });
    const sub = db.prepare("SELECT * FROM submissions WHERE id=?").get(req.params.id);
    if (!sub) return res.status(404).json({ error: "submission 不存在" });
    const { mode } = req.body || {};
    if (mode !== "all" && mode !== "restricted")
      return res.status(400).json({ error: "mode 必须是 all 或 restricted" });
    const prevVis = parseMeta(sub).visibility || null;
    const memberEmails =
      sub.type === "mcp"
        ? db
            .prepare("SELECT DISTINCT member FROM mcp_member_tokens WHERE submission_id=?")
            .all(sub.id)
            .map((r) => r.member)
        : [];
    const { visibility, adoptMembers } = resolveVisibilitySave(prevVis, req.body || {}, memberEmails);
    // 管理员显式保存可见范围 = 完成「上线」配置；此后该条目才对所选范围开放可见/下载/调用
    patchMeta(sub.id, { visibility, visibility_configured: true });
    // Skill 上架：此前未发布到 Registry（approve 时延后），此刻才发布，使其对目录/用户可发现
    if (sub.type === "skill") {
      registryPublish(sub.id).catch((e) => logger.error("同步 Registry 失败(上架):", sub.id, e && e.message));
    }
    audit(req, "visibility_change", sub.type, sub.id, {
      from: prevVis, to: visibility,
      adopt_members: adoptMembers || undefined,
      payload_users_ignored: mode === "all" && Array.isArray((req.body || {}).users) ? true : undefined,
    });
    res.json({ id: sub.id, visibility, visibility_configured: true, adopt_members: adoptMembers });
  });

  // 镜像来源分级查询：供提交表单做实时提示。
  // 白名单/内网地址以后端配置为准，避免前端另存一份导致两边不一致。
  app.get("/registry/classify", (req, res) => {
    const ref = String(req.query.ref || "").trim();
    if (!ref) return res.status(400).json({ error: "ref 必填" });
    const cls = classifyRegistry(ref);
    res.json({
      ref,
      internal_registry: INTERNAL_REGISTRY,
      internal_only: INTERNAL_ONLY,
      trusted_registries: TRUSTED_REGISTRIES,
      ...cls,
    });
  });

  // 审批通过 → 管理者确认发布。普通用户提交不带运行地址，MCP 的运行端点由
  // 平台在此异步调 ToolHive 部署后自动回填（见 deployMcp）。
  app.post("/submissions/:id/approve", async (req, res) => {
    const { id } = req.params;
    const { admin_id, reason, override_scan, confirm_prompt_review, exempt_network } = req.body || {};
    const sub = db.prepare("SELECT * FROM submissions WHERE id=?").get(id);
    if (!sub) return res.status(404).json({ error: "submission 不存在" });
    let meta = parseMeta(sub);
    // ---- 安全扫描闸门（P0 安全链）----
    // Trivy CRITICAL/secret 未特批 → 422，管理员须显式 override_scan=true（写审计）
    if (meta.trivy && meta.trivy.status === "critical" && !override_scan) {
      audit(req, "approve_denied", sub.type, id, { reason: "trivy critical", trivy: meta.trivy }, "denied");
      return res.status(422).json({
        error: "扫描发现 CRITICAL 漏洞或明文密钥，需管理员显式确认放行：请携带 override_scan=true 重新提交审批。",
        trivy: meta.trivy,
      });
    }
    // Skill 提示词注入 alert 未人工确认 → 422，须显式 confirm_prompt_review=true（写审计）
    if (sub.type === "skill" && meta.prompt_scan && meta.prompt_scan.status === "alert" && !confirm_prompt_review) {
      audit(req, "approve_denied", sub.type, id, { reason: "prompt injection alert", prompt_scan: { status: meta.prompt_scan.status, total: meta.prompt_scan.total } }, "denied");
      return res.status(422).json({
        error: "SKILL.md 提示词注入规则命中 alert，需人工逐条审阅并勾选确认：请携带 confirm_prompt_review=true 重新提交审批。",
        prompt_scan: meta.prompt_scan,
      });
    }
    // 两段式豁免第 2 段：审批授权。admin 显式勾选（exempt_network=true）才写标记，
    // 提交者的 data_source 声明只是意图，永远不能自己生效。授权随审批进审计轨迹。
    if (exempt_network === true || exempt_network === "true") {
      meta.network_exempt = true;
    }
    db.prepare("UPDATE submissions SET status='approved', meta=? WHERE id=?")
      .run(JSON.stringify(meta), id);
    db.prepare("INSERT INTO approvals VALUES(?,?,?,?,?,?)")
      .run("ap_" + Date.now(), id, admin_id || "admin", "approved", reason || "", new Date().toISOString());
    audit(req, "approve", sub.type, id, {
      reason: reason || "", admin_id: admin_id || "admin",
      override_scan: Boolean(override_scan), confirm_prompt_review: Boolean(confirm_prompt_review),
      exempt_network: meta.network_exempt === true,
      data_source: meta.data_source || null,
      trivy_status: meta.trivy ? meta.trivy.status : "none",
      prompt_scan_status: meta.prompt_scan ? meta.prompt_scan.status : "none",
    });
    // 同步到 Registry Server：先落注册名/版本，便于后续下线/删除时定位条目
    const gv = ensureGroupMeta(sub);
    ensureRegistryMeta(sub);
    // 2026-09-08：active_versions 指针已废弃——用户侧版本下拉可自选已上架版本，
    // 目录默认展示"最新已上架版本"（见 pickDisplayVersions），不再维护激活指针。
    if (sub.type === "skill") {
      // 审批通过：先把 staging 待审暂存区的制品提升(promote)到 published 已发布区。
      // 注意：不在此处 registryPublish —— Skill 默认未上线(visibility_configured=false)，
      // 须等管理员配置可见范围（上架）后才发布到 Registry 目录，真正对用户可发现可下载。
      const m0 = parseMeta(sub);
      if (m0.artifact_key && m0.artifact_key.startsWith("staging/")) {
        const gk = m0.group_key || sub.payload_ref;
        const ver = m0.version || "1.0.0";
        const fn = m0.artifact_filename || path.basename(m0.artifact_key);
        const pub = await promoteArtifact(m0.artifact_key, gk, ver, fn).catch((e) => {
          logger.error("[artifact] 提升至已发布区失败(保留原 key):", m0.artifact_key, e && e.message);
          return null;
        });
        if (pub) {
          patchMeta(id, { artifact_key: pub });
          logger.info("[artifact] 已提升至已发布区:", m0.artifact_key, "->", pub);
        }
      }
      // 解包 Skill 包提取 README 与文件树（仅当存在制品），结果回写 meta 供详情页展示
      const mInspect = parseMeta(sub);
      if (mInspect.artifact_key) {
        inspectSkillPackage(mInspect.artifact_key).then((insp) => {
          if (insp) patchMeta(id, {
            skill_readme: insp.readme,
            skill_readme_name: insp.readme_name,
            skill_tree: insp.tree,
            skill_file_count: insp.file_count,
          });
        }).catch((e) => logger.error("[inspect] skill 解包失败:", id, e && e.message));
      }
    }
    // MCP：审批通过只把制品提升到已发布区 + 落 meta，不再自动部署。
    // 部署改为管理员在「已发布管理/审核队列」里单独点「部署」，成功后再发布到 Registry。
    if (sub.type === "mcp") {
      // tar 提交：把 staging 待审制品提升(promote)到 published 已发布区，供详情页/后续部署读取；
      // 部署按钮内会再 docker load 并 thv run。
      if (meta.source_type === "tar" && meta.artifact_key) {
        if (meta.artifact_key.startsWith("staging/")) {
          const gk = meta.group_key || sub.payload_ref;
          const ver = meta.version || "1.0.0";
          const fn = meta.artifact_filename || path.basename(meta.artifact_key);
          const pub = await promoteArtifact(meta.artifact_key, gk, ver, fn).catch((e) => {
            logger.error("[artifact] tar 制品提升至已发布区失败(保留原 key):", meta.artifact_key, e && e.message);
            return null;
          });
          if (pub) {
            patchMeta(id, { artifact_key: pub });
            logger.info("[artifact] tar 已提升至已发布区:", meta.artifact_key, "->", pub);
          }
        }
      }
      // 部署状态保持未设置（即 unborn / 未部署），管理员在「已发布管理」里点「部署」才真正拉起。
      // 不写 deploy_status，让前端按其默认态渲染「未部署 + 部署按钮」。
      // 源码包提交（source_type=source）：解包提取 README 回写 meta，供详情页 README 标签展示。
      // 复用 Skill 包解包逻辑，失败不阻断审批主流程。
      if (meta.source_type === "source" && meta.artifact_key) {
        inspectSkillPackage(meta.artifact_key).then((insp) => {
          if (insp) patchMeta(id, {
            mcp_readme: insp.readme,
            mcp_readme_name: insp.readme_name,
            mcp_tree: (insp.tree || []).slice(0, MCP_TREE_MAX),
            mcp_file_count: insp.file_count,
            mcp_readme_inspected: MCP_README_INSPECT_VERSION,
          });
        }).catch((e) => logger.error("[inspect] mcp 源码包解包失败:", id, e && e.message));
      }
    }
    res.json({ id, status: "approved" });
  });

  // 重新部署（失败后重试 / 镜像更新后）
  app.post("/submissions/:id/deploy", async (req, res) => {
    const { id } = req.params;
    const sub = db.prepare("SELECT * FROM submissions WHERE id=?").get(id);
    if (!sub) return res.status(404).json({ error: "submission 不存在" });
    if (sub.type !== "mcp") return res.status(400).json({ error: "只有 MCP 可部署" });
    // 部署门禁：必须先由管理员在「可见范围」里显式配置并保存，才算上线、才允许部署
    const dm = parseMeta(sub);
    if (!isOnShelf(dm)) {
      return res.status(400).json({
        id,
        deploy_status: "blocked",
        error: "该 MCP 尚未上线：请先在「可见范围」里选择可查看/调用它的成员或组并保存，之后才能部署。",
      });
    }
    try {
      await deployMcp(id);
    } catch (e) {
      // DEPLOY_BUSY：同一 MCP 已有部署/下线在进行，拒绝并发触发（前端提示稍后再试）
      if (e && e.code === "DEPLOY_BUSY") return res.status(409).json({ id, error: e.message });
      return res.status(500).json({ id, error: "部署触发失败: " + (e && e.message) });
    }
    const m = parseMeta(db.prepare("SELECT meta FROM submissions WHERE id=?").get(id));
    audit(req, "deploy", sub.type, id, { workload: m.workload_name, deploy_status: m.deploy_status, deploy_error: m.deploy_error || "", image: m.deployed_image || "" }, m.deploy_status === "failed" ? "error" : "success");
    if (m.deploy_status === "failed") {
      return res.status(500).json({ id, deploy_status: "failed", error: m.deploy_error || "部署失败" });
    }
    res.json({ id, deploy_status: m.deploy_status || "deploying" });
  });

  // 下线：停止容器、清空运行端点，但保留 Registry 目录条目（MCP 界面仍可见）。
  app.post("/submissions/:id/undeploy", async (req, res) => {
    const { id } = req.params;
    const sub = db.prepare("SELECT * FROM submissions WHERE id=?").get(id);
    if (!sub) return res.status(404).json({ error: "submission 不存在" });
    if (sub.type !== "mcp") return res.status(400).json({ error: "只有 MCP 可下线" });
    try {
      await undeployMcp(id);
    } catch (e) {
      if (e && e.code === "DEPLOY_BUSY") return res.status(409).json({ id, error: e.message });
      return res.status(500).json({ id, error: "下线触发失败: " + (e && e.message) });
    }
    audit(req, "undeploy", sub.type, id, {});
    res.json({ id, deploy_status: "undeployed" });
  });

  // 重新同步到 Registry Server（同步失败后重试 / 补发布）。
  // 仅已发布条目可触发；MCP 需先有运行端点，否则会被 registryPublish 标记 skipped:no-endpoint。
  app.post("/submissions/:id/sync", async (req, res) => {
    const { id } = req.params;
    const sub = db.prepare("SELECT * FROM submissions WHERE id=?").get(id);
    if (!sub) return res.status(404).json({ error: "submission 不存在" });
    if (sub.status !== "approved")
      return res.status(400).json({ error: "仅已发布条目可同步到 Registry" });
    await registryPublish(id);
    const m = parseMeta(db.prepare("SELECT meta FROM submissions WHERE id=?").get(id));
    const rs = m.registry_synced || "";
    if (rs === "error") {
      return res.status(500).json({ id, registry_synced: rs, error: m.registry_sync_error || "同步失败" });
    }
    if (rs === "skipped:no-endpoint") {
      return res.status(400).json({ id, registry_synced: rs, error: "该 MCP 尚未成功部署运行（无可用端点），无法同步到 Registry。请先点击「部署」使其启动并产出端点后，再执行同步。" });
    }
    audit(req, "registry_sync", sub.type, id, { registry_synced: rs, error: m.registry_sync_error || "" }, rs === "error" ? "error" : "success");
    res.json({ id, ok: true, registry_synced: rs });
  });

  // 查询某逻辑产品下的所有已发布版本（MCP / Skill 多版本管理）
  // （原 GET /active-versions 与 POST /groups/:group_key/activate/:id 已随激活指针废弃移除）
  app.get("/groups/:group_key/versions", (req, res) => {
    const { group_key } = req.params;
    const versions = listGroupVersions(group_key).map((s) => {
      const m = parseMeta(s);
      return {
        id: s.id,
        payload_ref: s.payload_ref,
        version: m.version || "1.0.0",
        name: m.name || s.payload_ref,
        endpoint: m.endpoint || "",
        download_url: m.download_url || "",
        deploy_status: m.deploy_status || "unborn",
        registry_synced: m.registry_synced || "",
        on_shelf: isOnShelf(m), // 是否已上线（管理员配过可见范围）——仅上架版本可被普通用户选择
        created_at: s.created_at,
      };
    });
    res.json({ group_key, versions });
  });

  // 生命周期状态变更（管理者操作：下架 deprecated / 删除 removed 等）
  // 真实同步到 Registry Server（thv-registry-api）的发布/删除会同步执行，
  // 确保 Cloud UI /catalog 中的状态与管理后台一致。
  app.post("/submissions/:id/status", async (req, res) => {
    const { id } = req.params;
    const { status, admin_id, reason } = req.body || {};
    const sub = db.prepare("SELECT * FROM submissions WHERE id=?").get(id);
    if (!sub) return res.status(404).json({ error: "submission 不存在" });
    const allowed = ["pending", "approved", "deprecated", "removed", "rejected"];
    if (!allowed.includes(status)) {
      return res.status(400).json({ error: "非法的状态: " + status });
    }
    db.prepare("UPDATE submissions SET status=? WHERE id=?").run(status, id);
    db.prepare("INSERT INTO approvals VALUES(?,?,?,?,?,?)")
      .run("ap_" + Date.now(), id, admin_id || "admin", "status:" + status, reason || "", new Date().toISOString());
    audit(req, "status_change", sub.type, id, { from: sub.status, to: status, reason: reason || "" });

    // 拒绝(rejected) 与 删除(removed)：用户上传的制品（Skill zip / MCP tar）已不再需要，
    // 立即释放存储，避免无人回收导致磁盘堆积。下架(deprecated)按设计保留（保温、可恢复），不动制品。
    if (status === "rejected" || status === "removed") {
      deleteSubmissionSecrets(id); // .env 私密配置的凭据库条目同步清除
      const m = parseMeta(sub);
      // 源码构建产生的本地镜像一并清理
      if (m && m.source_type === "source" && m.built_image) {
        ctx.execFileHidden("docker", ["rmi", "-f", m.built_image], { timeout: 30000, maxBuffer: MAX_BUFFER }).catch(() => {});
      }
      if (m && m.artifact_key) {
        try {
          await objStore.del(m.artifact_key);
          logger.info("[artifact] 已清理制品:", m.artifact_key, "(submission:", id, "status:", status, ")");
        } catch (e) {
          logger.error("[artifact] 清理制品失败:", m.artifact_key, e && e.message);
        }
      }
    }

    // 「删除(removed)」：停容器 + 清端点 + 从 Registry 移除 + 清理制品
    // 兜底：单步失败不阻断，保证接口最终能给出响应（否则前端拿不到结果会白屏）
    // hard:true —— 删除提交必须 thv rm 整组移除（下线语义的 stop 会留下已停容器成为孤儿）
    if (status === "removed" && sub.type === "mcp") {
      try {
        await undeployMcp(id, { hard: true });
      } catch (e) {
        if (e && e.code === "DEPLOY_BUSY") {
          // 删除撞上部署/下线进行中：回滚刚写的状态（审批流水保留作痕迹），409 让管理员稍后重删
          db.prepare("UPDATE submissions SET status=? WHERE id=?").run(sub.status, id);
          return res.status(409).json({ id, error: "该 MCP 正在部署/下线中，请等待当前操作完成后再删除" });
        }
        logger.error("[lifecycle] 删除时停止实例失败:", id, e && e.message);
      }
    }

    // 「下架(deprecated)」：仅从 Registry 移除目录条目，对用户隐藏；运行实例继续保留，
    // 以便「恢复上架」时无需重新部署即可重新显示。Skill 无容器，同样只删 Registry。
    // 「删除(removed)」：同样从 Registry 移除目录条目。
    if (status === "removed" || status === "deprecated") {
      await registryDelete(id);
    }

    // 恢复上架（approved）：只恢复目录可见性（重新发布到 Registry）。
    // 部署状态（deployed / undeployed / deploying / failed）由「部署 / 下线」独立维护；
    // 上下架属于可见性维度，绝不触碰运行态——否则会出现「容器仍在运行、界面却显示已下线」。
    if (status === "approved") {
      await registryPublish(id);
    }

    res.json({ id, status });
  });

  // 管理员手动重跑安全扫描（Trivy + 注入规则），结果回写 meta
  app.post("/submissions/:id/rescan", async (req, res) => {
    const actor = actorFromReq(req);
    if (!actor.admin) return res.status(403).json({ error: "仅管理员可重跑扫描" });
    const sub = db.prepare("SELECT * FROM submissions WHERE id=?").get(req.params.id);
    if (!sub || sub.type !== "mcp" && sub.type !== "skill") return res.status(404).json({ error: "submission 不存在" });
    runSubmissionScans(sub.id, sub.type);
    audit(req, "rescan", sub.type, sub.id, {});
    res.json({ id: sub.id, status: "scanning" });
  });
};

#!/usr/bin/env node
// 拆分完整性对账：每个 routes/services 模块"实际访问的 ctx 字段"（Proxy 实测）
// 与 server.js 装配时"实际提供的字段"（静态解析装配块 + CTX 属性集）逐项 diff。
"use strict";
const fs = require("node:fs");
const path = require("node:path");

const ROOT = __dirname + "/..";
const serverSrc = fs.readFileSync(path.join(ROOT, "server.js"), "utf8");

// ---------- 1. Proxy 实测各模块访问的 ctx 字段 ----------
const MODS = [
  "routes/favorites.js", "routes/stats.js", "routes/issues.js", "routes/audit.js",
  "routes/skills.js", "routes/mcp.js", "routes/submissions.js",
  "routes/submission-upload.js", "routes/submission-env.js",
  "services/deploy.js",
];
const need = {};
for (const f of MODS) {
  const accessed = new Set();
  const ctxProxy = new Proxy({}, { get(t, k) { accessed.add(String(k)); return function () {}; } });
  const appProxy = new Proxy({}, { get(t, k) { return function () {}; } });
  try {
    const m = require(path.join(ROOT, f));
    // deploy.js 是 createDeployService(ctx) 单参；其余 (app, ctx)
    if (f.includes("services/")) m(ctxProxy);
    else m(appProxy, ctxProxy);
  } catch (e) {
    console.log("[加载异常]", f, String(e.message).slice(0, 80));
  }
  need[f] = [...accessed].sort();
}

// ---------- 2. 静态提取 CTX 的属性集 ----------
// CTX 对象字面量（594 行区）+ Object.assign(CTX, {...}) + CTX.xxx = 赋值
const ctxProps = new Set();
// 2a. CTX 字面量内短属性（逐行找 "  xxx," / "  xxx:" 模式，取 CTX 定义段）
const ctxDefMatch = serverSrc.match(/const CTX = \{([\s\S]*?)\n\};/);
if (ctxDefMatch) {
  for (const line of ctxDefMatch[1].split("\n")) {
    const names = line.match(/([A-Za-z_$][\w$]*)\s*[,:}]/g) || [];
    for (const n of names) ctxProps.add(n.replace(/[\s,:}]/g, ""));
  }
}
// 2b. Object.assign(CTX, {...})
for (const m of serverSrc.matchAll(/Object\.assign\(CTX,\s*\{([\s\S]*?)\}\)/g)) {
  for (const n of m[1].match(/([A-Za-z_$][\w$]*)\s*[,:]/g) || [])
    ctxProps.add(n.replace(/[\s,:]/g, ""));
}
// 2c. CTX.xxx = / CTX[...] =
for (const m of serverSrc.matchAll(/CTX\.([A-Za-z_$][\w$]*)\s*=/g)) ctxProps.add(m[1]);
// 2d. getter 形式已在 2a 覆盖（"get TAR_ROOT()" 中 TAR_ROOT 会被抓到）
// 2e. env-secrets / source-build / scan / reconcile 的解构是否回挂 CTX：查解构后是否 Object.assign
const envSecretsBlock = serverSrc.match(/const \{\s*([\s\S]*?)\s*\} = require\("\.\/lib\/env-secrets"\)\(CTX\);/);
const sourceBuildBlock = serverSrc.match(/const \{\s*([\s\S]*?)\s*\} = require\("\.\/lib\/source-build"\)\(CTX\);/);
const scanBlock = serverSrc.match(/const \{\s*([\s\S]*?)\s*\} = require\("\.\/lib\/scan"\)\(CTX\);/);
// 这些 lib 的导出若被装配块显式列出就不依赖 CTX 回挂；此处仅记录以便人工核对
const libExports = {
  "env-secrets": envSecretsBlock ? envSecretsBlock[1].match(/[A-Za-z_$][\w$]*/g) : [],
  "source-build": sourceBuildBlock ? sourceBuildBlock[1].match(/[A-Za-z_$][\w$]*/g) : [],
  scan: scanBlock ? scanBlock[1].match(/[A-Za-z_$][\w$]*/g) : [],
};

// ---------- 3. 提取每个模块装配块提供的字段 ----------
const CTX_SET = ctxProps; // (app, CTX) 形态提供的字段就是 CTX 全集
function extractAssembly(modulePath) {
  // server.js 里的实际形态：require("./routes/favorites")（带 ./ 前缀、不带 .js）
  const rel = "./" + modulePath.replace(/\.js$/, "");
  const esc = rel.replace(/[/.]/g, "\\$&");
  // 形态A：(app, CTX) —— 提供即 CTX 全集
  const reA = new RegExp('require\\("' + esc + '"\\)\\(app,\\s*CTX\\)');
  if (reA.test(serverSrc)) return { set: CTX_SET, spreadCtx: false };
  // 形态B：(app, {...}) —— 对象字面量（可能含 ...CTX 展开）
  const reB = new RegExp('require\\("' + esc + '"\\)\\(app,\\s*\\{([\\s\\S]*?)\\}\\);');
  const mB = serverSrc.match(reB);
  if (mB) {
    const provided = new Set();
    let spread = false;
    const body = mB[1];
    if (/\.\.\.CTX/.test(body)) spread = true;
    for (const n of body.match(/[A-Za-z_$][\w$]*/g) || []) {
      if (["require", "CTX"].includes(n)) continue;
      provided.add(n);
    }
    if (spread) for (const c of CTX_SET) provided.add(c);
    return { set: provided, spreadCtx: spread };
  }
  // 形态C：services/deploy —— __deployService = require(...)({...}) 单参
  const reC = new RegExp('require\\("' + esc + '"\\)\\(\\{([\\s\\S]*?)\\}\\)');
  const mC = serverSrc.match(reC);
  if (mC) {
    const provided = new Set();
    for (const n of mC[1].match(/[A-Za-z_$][\w$]*/g) || []) {
      if (["require"].includes(n)) continue;
      provided.add(n);
    }
    if (/\.\.\.CTX/.test(mC[1])) for (const c of CTX_SET) provided.add(c);
    return { set: provided, spreadCtx: true };
  }
  return null;
}

// ---------- 4. 逐模块 diff ----------
let totalMissing = 0;
for (const f of MODS) {
  const asm = extractAssembly(f);
  if (!asm) {
    console.log("⚠ 未找到装配块: " + f);
    totalMissing++;
    continue;
  }
  const missing = need[f].filter((n) => !asm.set.has(n));
  const tag = missing.length ? "✗ 缺 " + missing.length : "✓";
  console.log(`${tag} ${f} (需 ${need[f].length} / 供 ${asm.set.size})${missing.length ? ": " + missing.join(", ") : ""}`);
  if (missing.length) totalMissing += missing.length;
}

// ---------- 5. server.js 留守代码引用"已迁走标识符"扫描 ----------
// 取重构前(第一步之前)的 server.js 顶层定义名，凡当前 server.js 已无定义但仍出现引用的即嫌疑。
let oldSrc = null;
try { oldSrc = fs.readFileSync(path.join(ROOT, ".git-refcheck-old.js"), "utf8"); } catch (_) {}
if (!oldSrc) {
  console.log("\n(跳过留守引用扫描：无 .git-refcheck-old.js 基线文件)");
}
console.log("\n总计缺失: " + totalMissing);
process.exit(totalMissing ? 1 : 0);

#!/usr/bin/env node
// 安全关键路径自动化测试（重构护航网第二层）。
// 覆盖：rotate-token 权限矩阵、4100 对外口强制 Token、伪造身份头隔离、
//       回环口 restricted Token 强制、列表可见性过滤。
// 原则：不轮换任何真实条目的 Token、不改「新零售」可见性；
//       restricted 场景用临时 DB 条目（sec_test_*），测完立即删除。
// 运行：node scripts/security-test.js（backend 需在 4000/4100 运行中）
"use strict";

const BASE = "http://127.0.0.1:4000";
const EXT = "http://127.0.0.1:4100";
const INIT = {
  jsonrpc: "2.0",
  id: 1,
  method: "initialize",
  params: {
    protocolVersion: "2025-03-26",
    capabilities: {},
    clientInfo: { name: "sec-test", version: "1.0.0" },
  },
};

let pass = 0;
const fails = [];
function check(name, cond, detail = "") {
  if (cond) {
    pass++;
    console.log("  ✓ " + name);
  } else {
    fails.push(name + (detail ? " — " + detail : ""));
    console.log("  ✗ " + name + (detail ? " — " + detail : ""));
  }
}

async function req(url, opts = {}) {
  try {
    const r = await fetch(url, { signal: AbortSignal.timeout(8000), ...opts });
    let body = null;
    try {
      body = await r.json();
    } catch (_) {}
    return { status: r.status, body };
  } catch (e) {
    return { status: 0, body: null, error: String(e.cause?.code || e.message) };
  }
}
const post = (url, headers, payload = INIT) =>
  req(url, {
    method: "POST",
    headers: { "Content-Type": "application/json", ...headers },
    body: JSON.stringify(payload),
  });

(async () => {
  console.log("== A. rotate-token 权限矩阵（不轮换真实条目） ==");
  let r = await post(
    `${BASE}/submissions/sec_test_nonexistent/rotate-token`,
    { "x-actor-email": "someone@example.com" },
    {},
  );
  check("A1 非管理员 rotate 403", r.status === 403, "status=" + r.status);

  r = await post(
    `${BASE}/submissions/sec_test_nonexistent/rotate-token`,
    { "x-actor-email": "admin@example.com", "x-actor-admin": "1" },
    {},
  );
  check("A2 管理员对不存在 id 404", r.status === 404, "status=" + r.status);

  // 找一个真实 Skill 提交验证类型闸门（Skill 无代理 Token）
  const { default: null_ } = {};
  r = await post(
    `${BASE}/submissions/sub_1788423526647/rotate-token`,
    { "x-actor-email": "admin@example.com", "x-actor-admin": "1" },
    {},
  );
  check("A3 对 Skill 类型 rotate 400", r.status === 400, "status=" + r.status);

  console.log("== B. 4100 对外口强制 Token（真实条目，只读调用） ==");
  const betterSqlite3 = require("better-sqlite3");
